window.__Q=window.__Q||{};window.__Q["clin/5/A2"]=[{"q":"一位24岁男青年近日出现恶心、呕吐和腹泻症状，且吐泻次数逐日多，每日达10～20次。大便呈米泔水样，有一定程度的脱水。血压降低（收缩压为9.31～12kPa）（90～70mmHg），脉搏细速，血浆比重为1.031～1.040，24小时尿量在500ml以下。经问诊，该青年一周前从洪水疫区归来，曾饮用过生水。请问该男青年最可能感染哪种病原体","o":["产气荚膜梭菌","霍乱弧菌","金黄色葡萄球菌","伤寒沙门菌","变形杆菌"],"a":1,"e":"霍乱弧菌是霍乱的病原体，经污染水源经口感染，霍乱肠毒素使小肠上皮细胞cAMP升高、大量分泌水和电解质，形成米泔水样便并致严重脱水。"},{"q":"急性细菌性痢病程第5日，婴儿出现溶血性贫血、急性肾衰竭和血小板减少。这种被称为溶血性尿毒综合征的临床三联征是起因于","o":["志贺毒素的作用","肠壁广泛性受损","细菌入血并释放内毒素","不耐热肠毒素的作用","细菌的侵袭力"],"a":0,"e":"志贺毒素由痢疾志贺菌1型产生，抑制肠上皮和肾内皮细胞蛋白质合成、损伤血管内皮，导致溶血性贫血、血小板减少和急性肾衰竭三联征。"},{"q":"患儿，男，出生后27天。出生后1天即出现发热，经抗菌治疗，效果不佳。B超检查显示双肾肿大，肾实质内多发大小不等脓腔；取脓肿内容物进行培养，菌落呈黄绿色，镜检可见有隔菌丝，分生孢子梗顶端膨大形成球形顶囊，小梗双层，顶端的分生孢子呈链状排列，表面粗糙。该患儿可能是下列哪种病原体感染","o":["烟曲霉","杂色曲霉","黄曲霉","新型隐球菌","白假丝酵母菌"],"a":2,"e":"黄曲霉菌落呈黄色，顶囊球形或近球形，小梗双层、布满顶囊表面，分生孢子成链排列且表面有小棘；烟曲霉则为烧瓶状顶囊、单层小梗。"},{"q":"患儿，2月龄。喂服第1粒脊髓灰质炎减毒活疫苗后，第16天开始持续性发热，第21天发现右下肢活动不便。查体见右下肢肌力Ⅰ级，膝反射减弱，其余肢体无异常。初步诊断为疫苗相关麻痹性脊髓灰质炎（VAPP），为避免类似临床不良事件发生，可采取的措施是","o":["不使用减毒活疫苗","不使用灭活疫苗","先使用灭活疫苗，再使用减毒活疫苗","先使用减毒活疫苗，再使用灭活疫苗","灭活疫苗和减毒活疫苗同时使用"],"a":2,"e":"先接种灭活脊髓灰质炎疫苗建立肠道外免疫，再口服减毒活疫苗，可阻止疫苗株在肠道增殖并侵入中枢神经系统，从而避免疫苗相关麻痹型脊髓灰质炎。"},{"q":"一脑膜炎患者，疑为新生隐球菌感染。镜检脑脊液离心后的沉渣涂片，应选择的染色方法是","o":["瑞氏染色","革兰染色","墨汁负染法","棉蓝染色","吉姆萨染色"],"a":2,"e":"新型隐球菌荚膜厚且不着色，墨汁负染后背景黑暗，菌体周围形成一圈透明晕环，是脑脊液标本最简便的染色检查方法。"},{"q":"患者，男，35岁，屠宰工人。因发热、头痛、腓肠肌疼痛就诊。查体：体温39℃，眼结膜充血，浅表淋巴结肿大。行MAT检查，凝集效价为1∶800。注射大剂量青霉素治疗后出现寒战高热，血压下降。该症状出现的可能与下列哪种因素有关","o":["流感病毒包膜","新生隐球菌荚膜","钩端螺旋体释放的毒性物质及可溶性抗原","支原体神经毒素","立克次体脂多糖"],"a":2,"e":"青霉素大量杀灭钩端螺旋体后释放毒性物质和可溶性抗原，引起寒战、高热和血压下降，即赫氏反应。"},{"q":"一名未接种过卡介苗的健康中年人，做结核菌素试验是阳性，下列哪项解释不正确","o":["需要接种卡介苗","不需要接种卡介苗","对结核病有免疫力","细胞免疫功能正常","感染过结核分枝杆菌"],"a":0,"e":"未接种卡介苗者结核菌素试验阳性，说明已感染结核分枝杆菌、细胞免疫功能正常并具有一定免疫力，无须再接种卡介苗。"},{"q":"患者，男，22岁，因打架斗殴入狱。在入狱前例行体检中检出HIV抗体阳性。经询问，该患者多次嫖娼，多次聚众吸毒，曾因打架受伤接受过输血治疗。经检测CD4＋ T细胞低于200个/μl。关于该病例说法不正确的是","o":["该患者可能经由性接触感染HIV","该患者处于无症状潜伏期","该患者可能经由输血途径感染HIV","该患者可能经由吸毒共用针管感染HIV","该患者目前免疫力低下"],"a":1,"e":"CD4+T细胞低于200个/μL已属艾滋病期，免疫严重缺损，并非无症状潜伏期；该期病毒载量高，易发生机会性感染和肿瘤。"},{"q":"患者，男，14岁，学生。4天前无明显诱因突起头痛，进行性加重，伴畏寒、发热；1天前非喷射性呕吐内容物1次，无咖啡色液，无咳嗽咳痰。急性病容，嗜睡，咽稍红，皮肤黏膜无出血点，双侧扁桃体Ⅰ度肿大，左侧腮腺肿大及颌下腺肿大。脑膜刺激征阳性。血常规示白细胞总数及中性粒细胞无升高。查血、尿淀粉酶明显升高。脑脊液涂片墨汁负染阴性。该患者最可能的诊断是","o":["流行性乙型脑炎","结核性脑膜炎","流行性腮腺炎并发脑膜炎","新型隐球菌脑膜炎","脊髓灰质炎"],"a":2,"e":"腮腺肿大伴脑膜刺激征、血尿淀粉酶升高，符合腮腺炎病毒经血行侵犯中枢神经系统引起的脑膜炎；墨汁负染阴性可排除隐球菌。"},{"q":"患者，男，50岁。反复上腹疼痛不适8年，加重1天入院。患者于入院8年前开始，遇饥饿时偶感上腹隐痛不适，进食后缓解。入院7年前开始，上诉症状发作较为频繁且以胀痛、灼痛为主，多以辛辣刺激及不消化饮食为诱因，伴反酸嗳气，春季及秋冬季节交替时易发生，伴夜间痛，每次发作后进食可缓解。入院前1天，吃冷饮后上腹痛症状再次复发，伴黑便，糊状，共4次，每次约250g左右，渐感头昏心悸，不伴恶心呕血及畏寒发热。经查，以“消化性溃疡”收入住院。引起此患者“消化性溃疡”的病原菌生化反应结果是","o":["凝固酶试验阳性","尿素酶试验阳性","甲基红试验阳性","硫化氢试验阳性","VP试验阳性"],"a":1,"e":"幽门螺杆菌富含尿素酶，分解尿素产氨使培养基变碱，酚红指示剂呈红色，即尿素酶试验阳性，是快速鉴定的依据。"},{"q":"患儿，男，7岁。因“头顶部脓肿、糜烂1个月、发热2天”入院。查体可见头顶部约3cm×4cm斑块，表面糜烂，高低不平，有脓液溢出，基底发红，周围散在脓疱。取脓疱液涂片后棉蓝染色可见如箭头 所示结构。该类微生物细胞壁的主要成份是","o":["肽聚糖","脂蛋白","糖蛋白","几丁质","糖肽"],"a":3,"e":"官方题库缺失图片"},{"q":"某患者剧烈咳嗽入院，怀疑病原菌感染，经鲍-金培养基培养后形成细小、光滑、表面隆起、灰白色、不透明的珍珠样菌落，最可能是哪种病原体感染","o":["破伤风梭菌","白喉棒状杆菌","百日咳鲍特菌","结核分枝杆菌","流感嗜血杆菌"],"a":2,"e":"百日咳鲍特菌在鲍-金培养基上生长缓慢，形成细小、光滑、隆起、灰白色不透明的珍珠样菌落，结合剧烈咳嗽可作出判断。"},{"q":"在英国牧场中，一些牛近来出现明显的运动失调、震颤、恐惧、狂躁等症状。这些病牛最可能罹患的疾病是","o":["TME","CWD","BSE","FSE","CJD"],"a":2,"e":"牛海绵状脑病俗称疯牛病，1986年首发现于英国，由朊粒引起，病牛表现为运动失调、震颤、感觉过敏、恐惧和狂躁。"},{"q":"患者，女，45岁，因食入河鱼引起腹泻，去医院就诊。病程以急剧腹泻、呕吐开始，腹泻为无痛性，伴有因腹直肌痉挛而引起的腹痛；大便开始为泥浆样，迅速成为“米泔水”样，含大量片状黏液；大便量多，每次可超过1000ml，每日10余次；呕吐常为喷射性和连续性，呕吐物先为胃内容物，继而为清水样。涂片染色取粪便及呕吐物涂片作革兰染色镜检，可见革兰阴性弧菌。怀疑该患者患何种疾病","o":["胃肠炎","霍乱","伤寒","细菌性痢疾","大肠埃希菌感染"],"a":1,"e":"无痛性剧烈腹泻、米泔水样便、喷射性呕吐伴重度脱水是霍乱的典型表现，粪便涂片见革兰阴性弧菌，与副溶血性弧菌的血水样便不同。"},{"q":"患者，女，70岁，因尿路感染于5天前开始服用氨苄西林。现出现腹泻。取粪便标本培养，培养出大量革兰阳性葡萄球菌。请问腹泻发生的可能机制是","o":["菌群失调","细菌产生肠毒素","细菌侵袭肠黏膜所致","细菌内毒素作用于肠黏膜","抗生素使用时间不够"],"a":0,"e":"长期使用氨苄西林抑制肠道正常菌群，耐药的金黄色葡萄球菌大量繁殖引起腹泻，属抗生素诱发的菌群失调。"},{"q":"患儿，男，6岁，未接种过DPT疫苗，春季末因咳嗽于呼吸科就诊。2周前，患儿出现咳嗽和鼻塞，症状持续，无发热和寒战。3天前，患儿出现夜间咳醒，咳嗽剧烈，咳嗽后出现呕吐和呼吸困难，扁桃体无肿大，无脓性分泌物。次日，患儿咳嗽依然存在，再次因剧烈咳嗽而咳醒，咳嗽持续约10分钟，吸气出现吼声。该患儿最可能感染何种病原体","o":["百日咳鲍特菌","肺炎支原体","白喉棒状杆菌","肺炎链球菌","结核分枝杆菌"],"a":0,"e":"未接种百日咳疫苗的儿童出现阵发性痉挛性咳嗽、吸气吼声和咳后呕吐，是百日咳鲍特菌黏附纤毛上皮并产生毒素所致。"},{"q":"患儿，男，1个月，因多发皮疹入院。皮疹呈圆形，外周有丘疹，带有鳞屑，掌拓部有大疱。患儿母亲吸毒，母血RPR阳性。该患儿最有可能的诊断是","o":["梅毒","HIV垂直感染","风疹病毒感染","淋病","疱疹病毒"],"a":0,"e":"母亲RPR阳性，新生儿掌跖大疱、皮疹伴鳞屑，提示梅毒螺旋体经胎盘垂直传播引起的先天梅毒。"},{"q":"新生儿出生1周，出现全身弥漫性红疹。刮取红疹部位涂片革兰染色镜检发现革兰染色阳性、凝固酶阳性的球菌。引起该疾病的病原菌是","o":["金黄色葡萄球菌","表皮葡萄球菌","腐生性葡萄球菌","人葡萄球菌","B群链球菌"],"a":0,"e":"革兰阳性、血浆凝固酶阳性的葡萄球菌是金黄色葡萄球菌，其产生表皮剥脱毒素，可引起新生儿全身弥漫性红斑。"},{"q":"一年轻女性，近3天出现排尿困难和排尿次数增加。无发热、无皮疹。尿检发现每高倍镜下10～15个白细胞和大量细菌，细菌经染色为革兰阴性杆菌。可能为哪种细菌感染","o":["大肠埃希菌","志贺菌","伤寒沙门菌","解脲脲原体","淋病奈瑟菌"],"a":0,"e":"年轻女性首次尿路感染约90%由大肠埃希菌引起，尿中白细胞增多并见革兰阴性杆菌，符合尿路致病性大肠埃希菌感染。"},{"q":"患儿，男，5岁，咳嗽1个月。初起有发热、喷嚏、轻咳等症。现已不发热，但咳嗽日渐加重，尤夜间为重，为阵发性痉挛性咳嗽，伴呕吐。查体：患儿精神萎靡，面部水肿，眼结膜出血，舌系带溃疡，肺部未闻及啰音。实验室检查：白细胞总数达18×109/L。经红霉素治疗3天后症状减轻。其感染的病原菌最可能是","o":["肺炎链球菌","呼吸道合胞菌","腺病毒","肺炎支原体","百日咳鲍特菌"],"a":4,"e":"阵发性痉挛性咳嗽、鸡鸣样吼声、舌系带溃疡及白细胞升高，是百日咳鲍特菌感染的典型表现，红霉素治疗有效。"},{"q":"患儿，男，5岁，咳嗽3个月余。初起有发热、喷嚏、轻咳等症状。现已热退，但咳嗽日渐加重，尤以夜间为重，为阵发性痉咳伴有鸡鸣样吼声。查体：患儿精神萎靡，面部水肿，眼结膜出血，舌系带溃疡，肺部未闻及啰音。实验室检查：白细胞总数高达30×109/L。经红霉素治疗3天后症状减轻。其最可能感染的病原体是","o":["立克次体","螺旋体","真菌","病毒","细菌"],"a":4,"e":"百日咳鲍特菌是细菌，为革兰阴性短小杆菌、专性需氧；痉咳、鸡鸣样吼声及红霉素有效均提示细菌性感染。"},{"q":"患者，男，32岁，消瘦，出现腹胀、轻微腹泻达3个月，有同性恋史。体检发现鹅口疮。首先考虑应做的检查是","o":["乙肝病原学检查","粪便培养检测肠道致病菌","消化道钡餐造影","肥达反应检测","HIV抗体检测"],"a":4,"e":"消瘦、慢性腹泻、鹅口疮提示免疫功能严重受损，同性恋史为HIV感染高危因素，应首选HIV抗体检测明确诊断。"},{"q":"患者有丛林接触史，腿部皮肤被叮咬，局部出现溃疡，突发高热、皮疹。用变形杆菌OXk株作抗原与患者血清进行定量凝集试验，抗体效价为1∶320。该患者以上表现可能是由何种病原体引起","o":["普氏立克次体","恙虫病立克次体","斑疹伤寒立克次体","鹦鹉热衣原体","贝纳氏柯克斯体"],"a":1,"e":"丛林接触、叮咬处溃疡（焦痂）、高热皮疹，外斐反应OXK效价1∶320，符合恙虫病东方体感染。"},{"q":"患者，男，27岁，教师。3年前戒毒，近1年来双下肢麻木、乏力，进行性加重，近1个月不能行走，便秘，排尿不畅。当地颅脑及胸腰椎CT（－）。检查：双下肢肌力4°，胸10以下痛觉减退，关节位置及音叉觉正常，下肢腱反射亢进，Babinski（＋）。腰穿CSF压力160mmH2O，细胞35×106/L，蛋白1275mg/L，按脊髓炎治疗无效。查血RPR 1∶32，TPHA 1∶2560；腰穿CSF细胞25×106/L，蛋白1344mg/L，RPR 1∶2，TPHA 1∶1280。该患者最有可能是什么疾病","o":["化脓性脊髓炎","脊髓钩端螺旋体病","脊髓血管梅毒","病毒性脊髓炎","结核性脊髓炎"],"a":2,"e":"RPR与TPHA均阳性且脑脊液亦有反应，结合进行性脊髓损害和冶游史，符合梅毒螺旋体侵犯脊髓血管引起的脊髓血管梅毒。"},{"q":"一位65岁退休的女士，去墨西哥度假并食用当地食物。36小时后，她出现了大量的水样腹泻伴腹痛。她被诊断为大肠埃希菌相关性腹泻。下列哪种大肠埃希菌产生耐热和不耐热肠毒素","o":["EIEC","ETEC","EHEC","EPEC","EAEC"],"a":1,"e":"ETEC产生不耐热肠毒素和耐热肠毒素，分别激活肠上皮细胞cAMP或cGMP，引起分泌性水样腹泻，是旅行者腹泻的常见病原。"},{"q":"患者，男，40岁，农场工人。主诉全身无力，每日体温规律性升高再降低，夜里盗汗。取患者外周血，培养两周后发现革兰阴性小杆菌。该患者感染的病原体最有可能的是","o":["羊布鲁氏菌","空肠弯曲菌","大肠埃希菌","肠炎沙门菌","痢疾志贺菌"],"a":0,"e":"羊布鲁氏菌为革兰阴性小杆菌，生长缓慢，血培养需较长时间；农场接触病畜、波状热、盗汗和乏力符合布鲁菌病。"},{"q":"患儿，女，6岁。突起高热、头痛、呕吐伴有意识障碍，经血清学检查及脑脊液RT-PCR检查，诊断为“乙型脑炎”。引起该病的病原体的主要传播途径是","o":["消化道传播","输血传播","虫媒传播","呼吸道传播","直接接触传播"],"a":2,"e":"乙型脑炎病毒经蚊虫叮咬传播，三带喙库蚊是主要媒介，猪为扩增宿主，故虫媒传播是其主要传播途径。"},{"q":"一高校男性大学生，与男性伴侣有不洁性生活史6个月有余。为排除HIV感染，首选的病原学检测是","o":["HIV分离培养","Western blot检测HIV抗体","ELISA检测HIV抗体","ELISA检测HIV p24抗原","QRT-PCR检测HIV核酸"],"a":2,"e":"HIV感染初筛首选ELISA检测HIV抗体，阳性者再用蛋白质印迹法确认；抗体检测敏感性高、成本低，适合常规筛查。"},{"q":"患者，女，35岁，羊毛加工工人。因发烧、全身乏力、肌肉疼痛就诊，自述发烧3天，每天下午高烧，晚上体温下降。从患者血中分离到牛布鲁氏菌。关于牛布鲁氏菌的描述，正确的是","o":["是人类的条件致病菌","根兰阴性杆菌，主要通过肠毒素引起腹泻","有氧和无氧条件下均可生长，属于口腔正常菌群","通常感染牛，需要5%～10%CO2条件下培养","通常通过动物咬伤感染人类，引起人类出血热"],"a":3,"e":"牛布鲁氏菌初次分离需5%～10%CO2环境，营养要求高、生长缓慢；该菌为革兰阴性小杆菌，不经肠毒素致腹泻。"},{"q":"患者，男，49岁。3年来双下肢乏力，步态不稳，间有发麻，日渐加重。近3个月来加重，晚间无法行走。大小便不畅，便秘。查体：双下肢肌张力高，肌力3～4度，胸6以下痛觉稍减退，音叉觉及双足关节位置觉消失，腱反射活跃，双侧Babinski（＋）。曾按脊髓炎、亚急性联合变性治疗，病情继续发展，后发现双瞳孔不等圆，左2mm，右2.5mm，光反应极弱，调节反应灵敏。追问出冶游性病史（硬下疳）。对该患者进行实验室诊断，需做下列哪项筛查试验","o":["TPI","RPR","FTA-TBS","MHA-TP","TPHA"],"a":1,"e":"梅毒初筛选用RPR或TRUST等非密螺旋体抗原试验，操作简便、成本低；TPHA、TPI、FTA-ABS用于确认。"},{"q":"患儿，男，9岁。急性发热，体温持续39℃以上，咳嗽无痰，全身酸痛，稍气促，无发绀，双肺呼吸音粗，可闻及少量细湿啰音。血常规检查显示白细胞总数降低。血生化检查肌酸激酶、乳酸脱氢酶、天门冬氨酸氨基转移酶、丙氨酸氨基转移酶均升高。该患儿近期有病死禽密切接触史，捡到1只麻雀并饲养但是几天后死亡。该患儿最可能的诊断是","o":["普通感冒","大叶性肺炎","人感染高致病性禽流感","肺结核","严重急性呼吸综合征（SARS）"],"a":2,"e":"病死禽接触史、持续高热、咳嗽气促伴白细胞降低和肌酶升高，符合禽流感病毒H5N1等感染所致重症肺炎。"},{"q":"患者，女，30岁，持续发热10天，体温呈稽留热。查体：精神萎靡，反应淡漠，体温39.5℃，心率76次/min，肝肋下1.5cm，脾肋下2cm。白细胞3、2×109/L。肥达反应O 1∶320，H 1∶320。ALT 80U/L，血胆红素24μmol/L。该患者最可能的诊断是","o":["急性黄疸性肝炎","急性血吸虫病","伤寒合并中毒性肝炎","钩端螺旋体病","病毒性肝炎合并胆道感染"],"a":2,"e":"稽留热、相对缓脉、肝脾大、白细胞减少，肥达反应O与H均达1∶320，符合伤寒；转氨酶及胆红素升高提示合并中毒性肝炎。"},{"q":"患者，男，21岁。畏寒、高热，咳嗽伴左胸痛5天。查体：BP 80/50mmHg，心率120次/min。胸部X线片见左肺下叶大片状致密影。实验室检查：血WBC 12.2×109/L。该患者最可能感染的病原体是","o":["肺炎支原体","肺炎链球菌","军团菌","金黄色葡萄球菌","结核分枝杆菌"],"a":1,"e":"青壮年急性起病，寒战高热、胸痛、血压下降，X线示肺叶大片致密影，符合肺炎链球菌引起的大叶性肺炎伴休克。"},{"q":"患者，女，19岁，因咳嗽、发热、乏力就诊。拍胸片发现右肺有片状阴影，痰标本抗酸染色阳性，诊断为肺结核病。以下说法正确的是","o":["常见病原体为牛型结核分枝杆菌","可经呼吸道途径传播","可经蚊虫叮咬传播","原发肺结核病灶易形成空洞","继发肺结核只能是外源性感染"],"a":1,"e":"结核分枝杆菌主要经呼吸道飞沫传播，也可经消化道和破损皮肤感染；病灶形成空洞多见于继发型肺结核。"},{"q":"患者，男，12年前曾被诊断为慢性乙型肝炎，近期化验结果为HBsAg（－）、HBsAb（－）、HBeAb（﹢）、HBcAb（＋），转氨酶明显升高，抗-HAV（－），抗-HCV（－），抗-HDV（－），抗-HEV（－）。对该结果的说明正确的是","o":["对HBV具有免疫力","可能为HBV和HDV合并感染","患者乙型肝炎已经痊愈","患者可能发生了HBsAg变异","患者具有较大传染性"],"a":3,"e":"HBsAg与抗-HBs均阴性而抗-HBc、抗-HBe阳性，伴转氨酶升高，提示S基因突变致HBsAg抗原性改变、常规方法不能检出。"},{"q":"患儿，女，5岁，因高热、意识模糊而入院。查体发现该患儿面色苍白，昏迷，时有惊厥，呼吸微弱。粪便：白细胞4个/HP。血常规：白细胞数16×109/L。脑脊液正常。粪便取材培养，革兰染色为阴性杆菌，动力试验阴性。诊断患儿感染","o":["鼠伤寒沙门菌","肠产毒型大肠埃细菌","肠致病型大肠埃细菌","轮状病毒","痢疾志贺菌"],"a":4,"e":"痢疾志贺菌革兰阴性、无鞭毛、动力阴性，内毒素引起高热、惊厥等中毒症状，粪便少量白细胞符合中毒型菌痢。"},{"q":"一女性患者47岁，自制盐腌花生米与海产品存贮在同一冰箱，食入后引起上腹部阵发性绞痛，继而腹泻、有血样便。后出现恶心、呕吐，体温38.2℃，发病6小时后症状减轻，12小时症状消失痊愈。该女士可能感染下列哪种病原菌","o":["霍乱弧菌","副溶血性弧菌","幽门螺旋杆菌","空肠弯曲菌","蜡样芽孢杆菌"],"a":1,"e":"副溶血性弧菌存在于海产品，污染盐腌食品后引起阵发性腹绞痛、血水样便，病程短、恢复快，符合食物中毒。"},{"q":"农村患儿5岁，突起高热，体温40℃，头痛、恶心呕吐、嗜睡，查体有颈项强直，未见明显皮疹。最可能的疾病是","o":["登革热","流行性感冒","流行性乙型脑炎","出血热","麻疹"],"a":2,"e":"夏秋季农村儿童突起高热、头痛呕吐、嗜睡及颈项强直，无皮疹，符合乙型脑炎病毒经蚊传播引起的中枢感染。"},{"q":"患者，女，40岁，体检中发现其宫颈细胞有高度上皮间瘤样病变。有多个性伴侣和衣原体感染，已有5年未做过阴道细胞涂片检查。与该病例最有可能存在关联性的病毒是","o":["副黏病毒","黄病毒","人乳头瘤病毒","细小DNA病毒","风疹病毒"],"a":2,"e":"宫颈高度上皮内瘤变与高危型人乳头瘤病毒持续感染密切相关，HPV16、18型致癌性最强，多个性伴侣为危险因素。"},{"q":"患者，女，38岁，寒战高热，右侧胸痛3天。查体：T39.4℃，意识模糊，右下肺呼吸音减弱。血常规14.3×109/L，胸片示右下肺大片浸润阴影。该患者最可能诊断是","o":["克雷白杆菌肺炎","肺炎链球菌肺炎","肺炎支原体肺炎","干酪性肺炎","病毒性肺炎"],"a":1,"e":"寒战高热、胸痛，右下肺叩诊浊音、语颤增强并闻及湿啰音，X线见大片浸润影，符合肺炎链球菌引起的大叶性肺炎。"},{"q":"患者，男，45岁。患有慢性乙肝，3个月前因吸毒与他人共用针头导致感染HDV。此患者易于发展的结果是","o":["急性肝炎","慢性肝炎","慢性活动性肝炎","重型肝炎","原发性肝癌"],"a":3,"e":"慢性HBV感染者重叠感染HDV后，HDV借助HBsAg包膜复制，加重肝细胞损伤，常使病情急剧恶化，易发展为重型肝炎。"},{"q":"患者，男，32岁，经常出入酒吧、KTV，因下腹不适3周来就诊。查体：外生殖器见无痛性硬下疳，溃疡处有渗出液，初步诊断为梅毒。该病原体属于","o":["原核细胞型微生物","真核细胞型微生物","非细胞型微生物","朊病毒","亚病毒"],"a":0,"e":"梅毒螺旋体有细胞壁、核糖体和拟核，无完整细胞核，属原核细胞型微生物，其生物学地位介于细菌与病毒之间。"},{"q":"某女性患者因肺部细菌感染入院接受治疗。常规抗生素治疗效果不佳，考虑到可能是存在L型细菌的感染。此时，制作细菌培养基时，应考虑到","o":["细菌菌体内的渗透压","细菌菌体表面积大小","细菌的带电现象","细菌的化学组成","细菌的光学性质"],"a":0,"e":"L型细菌缺失细胞壁，不能耐受菌体内高渗，培养需用高渗低琼脂培养基，故配制时须考虑菌体内渗透压。"},{"q":"一烧伤患者入院后2天出现寒战、高热，体温40～41℃，呈弛张热，创面渗出绿色脓液伴有生姜味。实验室检查：白细胞总数和中性粒细胞升高，核左移并出现细胞内中毒性颗粒，嗜酸性粒细胞减少。临床诊断败血症，其病原菌可能是","o":["大肠埃希菌","金黄色葡萄球菌","变形杆菌","铜绿假单胞菌","白假丝酵母菌"],"a":3,"e":"烧伤创面出现绿色脓液伴生姜味，是铜绿假单胞菌感染的特征；该菌产生外毒素A、弹性蛋白酶等，多见于皮肤黏膜受损者。"},{"q":"患者，男，23岁。乏力，食欲缺乏，尿黄4天。双侧颈部淋巴结肿大，肝略大，脾肋下6cm。骨髓穿刺提示异型淋巴细胞＞50%，VCA-IgG（＋）。最可能的诊断是","o":["淋巴组织增生性疾病","急性感染性淋巴细胞增多症","急性淋巴细胞性白血病","病毒性肝炎","传染性单核细胞增多症"],"a":4,"e":"EBV原发感染后约半数表现为传染性单核细胞增多症，异型淋巴细胞增多、VCA-IgG阳性及颈淋巴结肿大支持诊断。"},{"q":"患者，男，76岁。慢性支气管炎急性发作，伴发热，体温39℃。头孢他啶治疗2周，症状有所缓解；但近两天再次出现发热并伴咳嗽咳痰。取痰标本进行病原体分离培养及鉴定，检出革兰阳性病原体，圆形、卵圆形菌体，鉴定为白假丝酵母菌。应选用下列哪种药物进行治疗","o":["氟康唑","罗红霉素","诺氟沙星","头孢哌酮钠","青霉素"],"a":0,"e":"白假丝酵母菌对氟康唑敏感，氟康唑抑制真菌麦角甾醇合成，是念珠菌病常用药物；其余均为抗菌药物。"},{"q":"患者，女，56岁。反复上腹部隐痛并伴嗳气，咽部梗噎感，食欲减退6个月。胃液检查发现幽门螺杆菌，诊断为慢性胃窦炎及溃疡。对诊断有确诊价值的菌体形态是","o":["蚕豆形的球菌","U形、S形或W形的螺杆菌","海鸥状的弧菌","飞蝇状的球杆菌","鱼群状的梭菌"],"a":1,"e":"幽门螺杆菌菌体呈弧形、U形、S形或W形，有鞭毛，常排列成鱼群状，这是与其他肠道菌鉴别的重要形态特征。"},{"q":"患儿，男，7岁，因头顶部脓肿、糜烂1个月、发热2天入院。家中养有一只兔，患儿经常与兔玩耍，该兔经常脱毛但没有引起重视。查体可见头顶部约3cm×4cm斑块，表面糜烂，高低不平，有脓液溢出，基底发红，周围散在脓疱。取脓疱液涂片后棉蓝染色可见如图所示结构，箭头所指为","o":["关节孢子","大分生孢子","小分生孢子","芽生孢子","孢子囊孢子"],"a":1,"e":"官方题库缺失图片"},{"q":"患者，男，50岁。1个月前出现间歇性发烧、游走性关节疼痛、全身乏力，发烧时体温38.5℃左右，退烧时体温可恢复正常；1周前病情加重就诊。患者从事农场牧羊工作，养殖的多只羊有流产现象。实验室检查，患者血清抗链O试验阴性，该患者最可能感染的是","o":["肺炎链球菌","布鲁氏菌","A族链球菌","流感病毒","风疹病毒"],"a":1,"e":"布鲁氏菌经接触病羊感染，表现为波状热、游走性关节痛、乏力及多汗，血培养可分离出革兰阴性小杆菌。"},{"q":"患者，女，32岁。食用毛蚶后出现发热、黄疸、厌油和肝大，诊断为“急性甲型肝炎”。该患者从体内排出病毒最多、传染性最强的时期是","o":["感染后1周内","发病2周后","发病前后2周内","发病后1个月","恢复期"],"a":2,"e":"甲型肝炎在潜伏期末至发病后2周内粪便排毒量最大，传染性最强；抗-HAV产生后粪便不再排毒。"},{"q":"成年男性，东北某地林场职工，春季植树后主诉发热、头痛、肌肉及关节疼痛。体温38.5℃，左背皮肤有暗红色椭圆形斑块，直径约18cm，中央颜色较深，腋下淋巴结肿大，肝脾触诊正常，白细胞8.5×109/L。该男子可能的诊断是","o":["钩端螺旋体病","风湿性关节炎","感冒","莱姆病","回归热"],"a":3,"e":"东北林区、蜱叮咬后出现慢性移行性红斑，伴发热、头痛、肌痛和局部淋巴结肿大，是伯氏疏螺旋体所致莱姆病。"},{"q":"一女患者，36岁，已确诊为AIDS患者，外周血中CD4＋ T细胞为300个/μl。对此患者进行抗病毒治疗的最佳治疗方案为","o":["蛋白酶抑制剂＋抗病毒中药制剂","2种核苷类药＋蛋白酶抑制剂","联用2种核苷类药","选用一种核苷类逆转录酶抑制剂","选用一种非核苷类逆转录酶抑制剂"],"a":1,"e":"HAART方案为2种核苷类逆转录酶抑制剂加1种非核苷类逆转录酶抑制剂或蛋白酶抑制剂，可最大限度抑制病毒复制。"},{"q":"张某，男，45岁。近半个月来尿道口轻度红肿，晨起有少许稀薄分泌物。淋球菌培养阴性，沙眼衣原体检查阴性，疑为解脲脲原体感染引起的非淋菌性尿道炎，拟行病原体培养协助诊断。下列不符合培养要求的是","o":["培养基中加入10%～20%的人或动物血清","培养基中加入酵母浸液","培养基pH为7.6～8","在微氧条件培养","用固体培养基培养"],"a":2,"e":"解脲脲原体最适pH为5.5～6.5，pH 7.6～8.0适宜其他支原体；培养尚需血清、酵母浸液及微氧环境，菌落呈油煎蛋样。"},{"q":"患者，女，35岁，患肺结核已3年，治疗不规则。2天前受凉后发热，体温38℃，体检无明显异常。胸片示两上肺斑片状阴影，伴不规则透亮区。为判断肺结核是否活动，可采取下列哪种方法","o":["痰结核杆菌检查","革兰染色","Elek平板毒力实验","糖发酵试验","胆汁溶解试验"],"a":0,"e":"痰中查找结核分枝杆菌是判断肺结核活动性和传染性的直接依据，涂片抗酸染色或培养阳性提示排菌。"},{"q":"患者，男，55岁，狩猎管理员。曾在小溪岸边捡起一只死麝鼠。4天后，患者右手食指出现1、5cm疼痛性溃疡，右前额1cm溃疡，右腋窝疼痛。体检发现右腋窝淋巴结肿大。该患者很可能感染的病原体是","o":["布鲁氏菌属细菌","立克次体","伤寒沙门菌","土拉热弗朗西丝菌","破伤风梭菌"],"a":3,"e":"土拉热弗朗西丝菌经接触病死野兔等啮齿动物传播，侵入处形成溃疡并伴局部淋巴结肿大，是野兔热的表现。"},{"q":"患者，男，38岁，因间断咳嗽气喘2个月，加重1周就诊。经检查初步诊断为支原体肺炎。下列哪种药物不能用于该患者治疗","o":["青霉素","红霉素","克拉霉素","阿奇霉素","诺氟沙星"],"a":0,"e":"支原体无细胞壁，β-内酰胺类抗生素如青霉素不能与之结合，故治疗无效；应选用大环内酯类或喹诺酮类。"},{"q":"患儿，女，3岁9个月。发热5天，双侧颈部淋巴结肿大，咽部充血，扁桃体肿大，眼睑水肿，异嗜性抗体阳性。最可能的诊断是","o":["急性扁桃体炎","传染性单核细胞增多症","颈部淋巴结炎","链球菌咽峡炎","巨细胞单核细胞增多症"],"a":1,"e":"发热、咽峡炎、颈部淋巴结肿大伴异嗜性抗体阳性，是EBV引起的传染性单核细胞增多症的典型表现。"},{"q":"某院外科医生在给一位乙型肝炎病毒（HBV）携带者手术时，不慎被手术剪刀割伤手指。为预防乙型肝炎病毒感染，应首先采取的措施是","o":["注射乙型肝炎疫苗","注射抗生素","注射丙种球蛋白","注射HBIg","注射α-干扰素"],"a":3,"e":"HBV意外暴露后应立即注射高效价抗-HBs的乙肝免疫球蛋白，中和入侵病毒；同时按程序接种乙肝疫苗。"},{"q":"患者，男，39岁，无烟酒嗜好，于15日前出差回来后出现乏力，恶心呕吐，排便每日4～5次。体温逐日上升，服用乳酸菌素和黄连素未见缓解，近一周持续在39、5～40℃。躯干隐约可见淡红色皮疹，直径2～3mm，压之褪色，右下腹压痛。下列除哪项检测外，结果为阳性均有助于诊断","o":["骨髓培养","血液培养","肥达反应","粪便培养","咽拭子培养"],"a":4,"e":"伤寒沙门菌经消化道感染，血、骨髓、粪便培养及肥达反应均有助诊断；咽拭子培养无诊断价值。"},{"q":"患者，18岁，头痛剧烈，喷射性呕吐，体温40℃，皮肤呈出血性淤斑。查脑膜刺激征（＋）。培养此病原菌应选用","o":["远藤氏培养基","博-金氏培养基","巧克力色培养基","吕氏培养基","罗氏培养基"],"a":2,"e":"脑膜炎奈瑟菌营养要求高，需在含血清或血液的巧克力色培养基上生长，普通培养基不能生长。"},{"q":"患者，女，38岁。外科创伤修复手术后，手术部位出现剧烈胀痛并伴随高热，血液培养分离出凝固酶阴性革兰染色阳性球菌。引起上述感染的可能性最大的病原菌是","o":["表皮葡萄球菌","金黄色葡萄球菌","肺炎链球菌","脑膜炎奈瑟菌","铜绿假单胞菌"],"a":0,"e":"凝固酶阴性葡萄球菌是植入物和术后感染常见病原，表皮葡萄球菌为皮肤正常菌群，易在异物表面形成生物膜。"},{"q":"患者，男，21岁，面部皮肤肿胀，双臂皮损广泛，痛触觉消失，指甲增厚，眉毛脱落。体检皮肤刮片抗酸染色可见胞浆呈泡沫状，临床诊断可能为何种病原体感染所致","o":["结核分枝杆菌","真菌","麻风分枝杆菌","肉毒梭菌","产气荚膜梭菌"],"a":2,"e":"麻风分枝杆菌抗酸染色阳性，寄生于巨噬细胞和施万细胞，胞质呈泡沫状的麻风细胞是其特征，临床可致感觉丧失和脱眉。"},{"q":"某地区发生数百人食物中毒的公共卫生事件，从患者的呕吐物中分离出革兰阳性、凝固酶阳性的球菌，可疑的病原菌最可能是","o":["希氏沙门菌","大肠埃希菌","C群链球菌","金黄色葡萄球菌","副溶血性弧菌"],"a":3,"e":"金黄色葡萄球菌产生肠毒素，污染食物后1～6小时引起呕吐腹泻；革兰阳性、凝固酶阳性是其鉴定要点。"},{"q":"患者，男，35岁，因输血感染HBV。其进行血清学检查时，通常不能检测到的成分是","o":["HBsAg","抗-HBs","HBeAg","抗-HBe","HBcAg"],"a":4,"e":"HBcAg组装于病毒衣壳内，一般不以游离形式存在于血液，常规血清学难以检出；临床检测的是其相应抗体。"},{"q":"患者，女，26岁，洗浴中心工作。近10日出现尿频、尿痛、并有轻微尿道灼烧感。查体可见外阴红肿，有脓性分泌物，自诉曾有不洁性交史，建议采集何种标本检测","o":["血液","尿道脓性分泌物","尿液","唾液","粪"],"a":1,"e":"淋病奈瑟菌侵犯尿道黏膜，取尿道口脓性分泌物涂片革兰染色，见中性粒细胞内革兰阴性双球菌即可诊断。"},{"q":"患者，女，68岁。自述1周前无明显诱因出现右侧腰部疼痛，夜间为甚；2日前疼痛加剧，痛如火燎，疼痛部位出现成簇疱疹。该患者可能患有","o":["麻疹","水痘","斑疹伤寒","带状疱疹","单纯疱疹"],"a":3,"e":"老年患者单侧腰背部剧痛后出现沿神经节段分布的成簇疱疹，是潜伏的VZV再激活引起的带状疱疹。"},{"q":"20岁男性患者咳嗽数周。1个月前开始感到疲劳，食欲减少，发热2周后咳痰中带血丝，体重减轻。体温38℃，非急性面容，右上肺有啰音，WBC 11×109/L，多形核63%。临床怀疑患肺结核，取痰做标本培养，常用哪种培养基","o":["血琼脂平板","罗氏（Lowenstein-Jensen）培养基","Border-Gengou培养基","巧克力色培养基","亚碲酸钾培养基"],"a":1,"e":"结核分枝杆菌培养常用罗氏培养基，含蛋黄、甘油、马铃薯等，生长缓慢，需4～8周才形成粗糙型菌落。"},{"q":"患儿，女，5岁，饭后6小时出现恶心、呕吐和腹泻等症状，粪便直接涂片显示革兰阳性球菌，进一步分离培养凝固酶玻片凝集试验阳性。可疑感染的细菌为","o":["A群链球菌","金黄色葡萄球菌","表皮葡萄球菌","腐生性葡萄球菌","奈瑟球菌"],"a":1,"e":"革兰阳性球菌、凝固酶玻片凝集阳性，结合进食后呕吐腹泻，符合金黄色葡萄球菌肠毒素引起的食物中毒。"},{"q":"8岁儿童因突发剧烈恶心、呕吐以及腹泻紧急入院就诊。患儿家长诉起病前4小时参加家庭生日聚会，患儿食用两大块生日蛋糕。检查患儿体温正常，入院观察后病情很快好转，未见明显后遗症。采集患儿呕吐物检测，染色镜检发现革兰阳性球菌。该患儿很可能是下列哪种病原菌感染","o":["淋病奈瑟菌","肺炎链球菌","金黄色葡萄球菌","表皮葡萄球菌","A群链球菌"],"a":2,"e":"进食蛋糕后4小时出现呕吐腹泻、体温正常且迅速恢复，呕吐物见革兰阳性球菌，符合金黄色葡萄球菌肠毒素食物中毒。"},{"q":"某急性乙型肝炎患者，用拉米夫定和干扰素治疗2个月后，血清HBV抗原抗体检查结果如下：HBsAg（＋），抗HBs（－），HBeAg（－），抗HBe（＋），抗HBc-IgM（－），抗HBc IgG（＋）。对该结果最好的解释是","o":["HBV感染急性期","病毒复制减弱，处于恢复期","无症状携带者","HBV复制活跃，血清传染性强","HBV已被清除"],"a":1,"e":"HBeAg转阴、抗-HBe阳转、抗-HBc以IgG为主，提示病毒复制减弱、传染性下降，处于乙型肝炎恢复期。"},{"q":"一男性青年发热休克，3天前开始头痛入院，当日意识不清，昏迷，体温41℃，血压70/30mmHg，躯干皮肤出现红色斑点。用药后血压仍继续下降，入院第3天死亡。血培养发现革兰阴性肾性双球菌生长。请问该病原菌的主要致病物质为","o":["荚膜","菌毛","外毒素","内毒素","芽孢"],"a":3,"e":"脑膜炎奈瑟菌为革兰阴性双球菌，其主要致病物质是细胞壁脂多糖内毒素，可引起发热、休克和DIC。"},{"q":"某中学，发生10例以发热、呕吐、腹泻为主的病例，并伴有里急后重、黏液脓血便的症状，临床诊断疑似细菌性痢疾，可能感染","o":["伤寒沙门菌","肠炎沙门菌","霍乱弧菌","志贺菌","肉毒梭菌"],"a":3,"e":"发热、里急后重、黏液脓血便，符合志贺菌经粪-口传播引起的细菌性痢疾，其侵袭结肠黏膜并释放内毒素。"},{"q":"患者，女，45岁，东南某地农民。因“剧烈头痛、肌肉酸痛、高热2天”就诊。查体：全身点状红疹，衣物和头发内发现体虱数只。体温39.5℃。外斐反应结果：OX19（1∶640），OX2（1∶160），OXK（-)。该患者感染的病原体是","o":["变形杆菌","支原体","普氏立克次体","斑疹伤寒立克次体","恙虫病立克次体"],"a":2,"e":"体虱为传播媒介，外斐反应OX19 1∶640而OXK阴性，结合高热、头痛、肌痛和皮疹，符合普氏立克次体所致流行性斑疹伤寒。"},{"q":"一青年近3天咳嗽，高热39℃，铁锈色痰，WBC18.5×109/L，X线胸片发现右肺中叶有大片阴影，临床诊断为大叶性肺炎、请问该致病菌的主要致病物质是","o":["鞭毛","荚膜","外毒素","内毒素","菌毛"],"a":1,"e":"铁锈色痰、肺叶大片实变及白细胞升高提示肺炎链球菌肺炎，其荚膜具有抗吞噬作用，是主要毒力因子。"},{"q":"患儿，男，2岁，因发热1天伴抽搐3次入院。查体：体温39.1℃，皮肤出现出血性淤斑。皮肤淤斑涂片镜检可见革兰染色阴性双球菌。该菌在固体培养基上生长形成","o":["露滴样菌落","菜花样菌落","羽毛样菌落","粗糙型菌落","油煎蛋样菌落"],"a":0,"e":"淤斑涂片见革兰阴性双球菌，提示脑膜炎奈瑟菌；该菌在巧克力色血平板上形成无色透明、露滴样菌落。"},{"q":"患儿，男，2岁。因腹泻住院，广谱抗菌药物治疗6天后症状明显好转停药，第9天再次发生腹泻，怀疑发生真菌所致二重感染。为确诊，正确的检查方法是","o":["显微镜检查","血清学试验","动物实验","核酸检测","真菌分离培养"],"a":4,"e":"广谱抗生素后再度腹泻提示二重感染，真菌分离培养见白色酵母样菌落可确诊，直接镜检仅能初筛。"},{"q":"某乙肝患者，近期两对半检查结果为：血清HBsAg（＋）、HBeAg（＋）及抗HBc IgM（＋）。对此结果解释不正确的是","o":["急性乙型肝炎","慢性乙型肝炎","乙型肝炎恢复期","无症状抗原携带者","血清有强传染性"],"a":2,"e":"HBsAg、HBeAg及抗-HBc IgM同时阳性提示病毒复制活跃、传染性强，见于急性或慢性乙型肝炎，不是恢复期。"},{"q":"患者，男，腿部皮肤被叮咬，突发高热，局部出现溃疡。入院体格检查、实验室检查诊断为斑疹伤寒立克次体感染。斑疹伤寒立克次体的传染源与储存宿主是","o":["人虱","鼠蚤","鼠","蜱","恙螨"],"a":2,"e":"斑疹伤寒立克次体的主要传染源和储存宿主为鼠等啮齿类动物，鼠蚤、鼠虱为传播媒介，鼠蚤亦起储存作用。"},{"q":"患儿，男，2岁。发热伴咳嗽，诊断为链球菌肺炎。用抗生素治疗的疗程应持续至体温正常后","o":["2～4天","5～7天","8～10天","11～13天","16～21天"],"a":3,"e":"链球菌肺炎抗菌治疗须足疗程，体温正常后仍需继续用药11～13天，总疗程约2周，以彻底清除残存细菌、防止复发。"},{"q":"患儿，男，1岁，因抽搐入院。上呼吸道感染2天，昨夜发热嗜睡。查体：颈强，体温40℃。WBC 17×109/L，腰穿脑脊液细胞数4×109/L，中性粒细胞占88%。诊断为细菌性脑膜炎。细菌培养时发现在预加的金葡菌菌落周围生长旺盛，出现卫星现象，G染色为G－杆菌。试问所感染的细菌可能是","o":["肺炎克雷伯菌","A群链球菌","脑膜炎奈瑟菌","流感嗜血杆菌","铜绿假单胞菌"],"a":3,"e":"流感嗜血杆菌在金黄色葡萄球菌菌落周围生长旺盛，越远越小，称卫星现象，因其需金葡菌提供的Ⅴ因子。"},{"q":"某托幼机构突发公共卫生事件，多名2岁以下幼儿出现发热、腹泻症状，粪便电镜下可见大量车轮状、具双层衣壳的球形病毒颗粒。对该病毒感染不具有诊断价值的微生物学检测方法是","o":["细胞培养分离病毒","RT-PCR检测病毒核酸","聚丙烯酰胺凝胶电泳检测","红细胞吸附试验","ELISA法检测病毒抗原"],"a":3,"e":"轮状病毒诊断依靠电镜、RT-PCR、聚丙烯酰胺凝胶电泳和ELISA检测抗原；红细胞吸附试验用于流感病毒，对轮状病毒无诊断价值。"},{"q":"7岁儿童，近日因皮肤不适到医院皮肤科门诊就诊。患儿家长诉患病初期皮肤表面出现红斑，并且在1～2天时皮肤表面出现褶皱，随后出现清亮的水泡。触碰患儿皮肤表面时，患儿哭闹不止，并有皮屑脱落。取皮肤样本进行微生物学检测，培养物能发酵甘露醇，在血琼脂平板上形成的菌落周围有完全透明的溶血环，此病原体最有可能是","o":["鼠疫耶尔森菌","霍乱弧菌","金黄色葡萄球菌","解脲脲原体","梅毒螺旋体"],"a":2,"e":"金黄色葡萄球菌发酵甘露醇，在血平板上形成完全透明的β溶血环，其表皮剥脱毒素引起红斑、水疱和表皮松解。"},{"q":"患儿，女，3岁。高热、咽痛、流涎、厌食、呕吐等。入院查体发现咽部充血，在咽腭弓、软腭、悬雍垂的黏膜上可见数个2～4mm大小灰白色的疱疹，周围有红晕，2日后破溃形成小溃疡。继发乙型流感。该患儿最可能的诊断是","o":["麻疹","手足口病","水痘","疱疹性咽峡炎","鹅口疮"],"a":3,"e":"发热咽痛，软腭、悬雍垂周围出现灰白色疱疹并破溃成溃疡，是柯萨奇A组病毒引起的疱疹性咽峡炎。"},{"q":"患者，男，36岁，野外作业中受伤。因伤口严重感染入院治疗。患者经林可霉素和头孢菌素治疗4天后，出现血水样腹泻并排出假膜，伴有发热、白细胞增多等全身中毒表现。初步诊断为假膜性结肠炎，可能由下列哪种病原体引起","o":["艰难梭菌","脆弱拟杆菌","产气荚膜梭菌","金黄色葡萄球菌","志贺菌"],"a":0,"e":"林可霉素等抗生素破坏肠道菌群后，艰难梭菌过度繁殖并产生毒素，引起假膜性结肠炎，表现为血水样腹泻和假膜。"},{"q":"患者，男，20岁。20天前无明显诱因出现前额部持续性疼痛，伴恶心呕吐、头晕目眩、颈部强直、精神淡漠，同时出现斜视、共济失调等中枢神经系统症状，且伴有发热。实验室检查：腰穿脑脊液（CSF）清亮，墨汁负染色，结果如图所示。白色箭头所指为","o":["厚膜孢子","关节孢子","芽生孢子","孢子囊孢子","分生孢子"],"a":2,"e":"官方题库缺失图片"},{"q":"患者青年男性，出现发热、不适、全身疼痛等症状。一天前出现持续高热，入院。查：患者相对缓脉，肝脾肿大，皮肤出现玫瑰疹，外周血白细胞明显下降，初步诊断为“肠热症”。引起该病的病原菌生化反应结果是","o":["分解乳糖只产酸","凝固酶试验阳性","尿素酶实验阳性","分解葡萄糖产酸不产气","枸橼酸盐利用试验阳性"],"a":3,"e":"肠热症由伤寒沙门菌引起，该菌分解葡萄糖产酸不产气，不发酵乳糖，据此可与大肠埃希菌等鉴别。"},{"q":"某女青年因咳嗽发热就诊，胸片发现右肺有片状阴影，结核菌素试验红肿直径大于2、0cm，该患者可能是","o":["机体对结核无免疫能力","结核病恢复期","结核病活动期","注射过卡介苗","感染过结核"],"a":2,"e":"结核菌素试验红肿直径大于2.0cm为强阳性，提示体内有活动性结核病灶，结合咳嗽发热和肺部阴影可判断为活动期。"},{"q":"患者，男，29岁。因尿道口轻度红肿并有少许稀薄分泌物1周就诊。根据症状和相关检查初步诊断为解脲支原体感染引起的非淋病性尿道炎。以下哪项对该病例确诊有意义","o":["巧克力培养基做病原体培养","取尿道分泌物做涂片染色镜检","特异性抗血清做生长抑制试验","冷凝聚试验","外斐反应检测"],"a":2,"e":"支原体无细胞壁，形态多变，用特异性抗血清做生长抑制试验或代谢抑制试验可鉴定菌种，特异性与敏感性均高。"},{"q":"20岁青年摘除扁桃体后，发热，出现心力衰竭。采血培养细菌，血平板有草绿色溶血环小菌落形成。涂片染色为G＋链状排列球菌，诊断为甲型溶血性链球菌心内膜炎。下列还有哪种菌能形成草绿色溶血环菌落","o":["金黄色葡萄球菌","乙型溶血链球菌","表皮葡萄球菌","丙型链球菌","肺炎链球菌"],"a":4,"e":"肺炎链球菌在血平板上形成细小菌落并产生草绿色α溶血环，与甲型溶血性链球菌相似，可借胆汁溶菌试验鉴别。"},{"q":"某幼儿园3岁小朋友，以发热、咽痛、呼吸困难入院。查体：体温38.5℃，口腔黏膜上散在白色斑点，咽部及扁桃体有一层灰白色膜。试问感染细菌经奈瑟染色后，观察到哪一结构有助于白喉的进一步诊断","o":["质粒","异染颗粒","荚膜","芽孢","鞭毛"],"a":1,"e":"白喉棒状杆菌含异染颗粒，用亚甲蓝或Albert染色呈深紫色，位于菌体两端，是形态学诊断的重要依据。"},{"q":"患者，男，45岁，因咳嗽、发热、头痛、咽喉痛4天就诊。查体：咽红充血，体温38.5℃。白细胞9×109/L，X线胸片显示左下肺薄片状阴影，冷凝聚试验（＋）。最可能的诊断是","o":["呼吸道合胞病毒肺炎","肺炎链球菌肺炎","肺炎衣原体肺炎","肺炎支原体肺炎","流感嗜血杆菌肺炎"],"a":3,"e":"青年患者咳嗽、咽痛、低热，肺部体征轻而X线有浸润影，冷凝集试验阳性，符合肺炎支原体肺炎。"},{"q":"患者，男，40岁，农民，突起发热、头晕与头痛一周就诊。查体：眼结膜充血、轻度黄疸、腓肠肌有明显压痛，初诊为钩体病。请问进行病原学检查的最适标本是","o":["尿液","脑脊液","外周血","眼结膜分泌物","唾液"],"a":2,"e":"钩端螺旋体病发病7～10天取外周血做病原学检查阳性率最高，两周后宜取尿液，有脑膜刺激征者取脑脊液。"},{"q":"患者，女，35岁。突起头痛，眼眶痛，腰痛，胸颈部点状瘀斑，尿量少，色红，浑浊。最可能的诊断是","o":["血小板减少性紫癜","猩红热","急性肾小球肾炎","肾综合征出血热","波浪热"],"a":3,"e":"发热、头痛、眼眶痛、腰痛伴皮肤瘀斑和少尿，是汉坦病毒引起肾综合征出血热的典型表现。"},{"q":"出生后10天新生儿，因眼睑水肿、有脓性分泌物就诊。检查发现患儿睑结膜弥漫性红肿，结膜炎症性乳头增生，初步诊断为新生儿化脓性结膜炎。涂片革兰染色未见革兰阴性双球菌，眼结膜刮片示多核白细胞增多，碘染色直接镜检发现包涵体。以下最可能的是","o":["淋球菌感染","沙眼衣原体感染","金葡菌感染","腺病毒感染","梅毒螺旋体感染"],"a":1,"e":"新生儿结膜炎，涂片未见革兰阴性双球菌，结膜刮片碘染色找到包涵体，提示沙眼衣原体感染。"},{"q":"患儿首次服脊髓灰质炎减毒活疫苗后，第21天出现发热、肢体乏力。查体显示四肢肌力0级，肌张力低，颈部以下皮肤痛觉缺失。麻痹第5天大便标本分离到脊髓灰质炎Ⅰ型病毒疫苗株，实验室检查未发现其他病原体感染，磁共振检查显示延髓、颈段、下胸段脊髓多发病变，胸11椎体水平以下脊神经前根强化较显著。该患儿最可能的诊断是","o":["海绵状脑病","流行性乙型脑炎","肉毒毒素中毒","无菌性脑膜炎","疫苗相关麻痹型脊髓灰质炎"],"a":4,"e":"服减毒活疫苗后21天出现不对称弛缓性麻痹，且分离到疫苗株，符合疫苗相关麻痹型脊髓灰质炎。"},{"q":"患者，男，28岁。近1周出现尿道口轻度红肿，晨起有少许稀薄分泌物。淋球菌培养阴性，支原体检查阴性，疑为衣原体感染。为确诊，下列处理方法中，错误的是","o":["尿道口拭子标本做衣原体核酸检测","尿道口拭子标本经抗生素无菌处理后鸡胚培养","尿道口拭子标本用膜式滤菌器除菌后做细胞培养","标本涂片用直接免疫荧光法镜检","标本涂片吉姆萨染色镜检"],"a":1,"e":"衣原体严格细胞内寄生，分离需用活细胞培养，鸡胚接种不是临床诊断方法；核酸检测和免疫荧光可直接查病原体。"},{"q":"患者有丛林接触史，腿部皮肤被叮咬，局部出现溃疡。突发高热，皮疹。经过医院相关检查诊断为立克次体感染。立克次体与革兰阴性菌相似，其中最重要的是","o":["都具有细胞壁","细胞壁中有肽聚糖和脂多糖","可在人工培养基上生长","均为二分裂方式繁殖","均具有DNA和RNA"],"a":1,"e":"立克次体属细胞壁含肽聚糖和脂多糖，与革兰阴性菌相似，但其外膜结构及寄生方式不同，东方体则不含肽聚糖。"},{"q":"患者，男，32岁。因车祸致右胫腓骨中段开放性骨折1小时入院治疗，入院后急诊行切开钢板内固定、石膏托外固定术。术后第3天查房时发现小腿中部有明显捻发感，伤口周围皮肤大部分呈紫红色，局部呈黑紫色，立即拆除缝线，见有暗红色的恶臭液体溢出，涂片检查显示革兰阳性粗大杆菌，急诊行截肢，残肢端缝合术，初步怀疑该男子是由哪种病原体感染致病","o":["破伤风梭菌","产气荚膜梭菌","肉毒梭菌","结核分枝杆菌","淋病奈瑟菌"],"a":1,"e":"伤口捻发感、皮肤紫红发黑、暗红色恶臭液体及革兰阳性粗大杆菌，是产气荚膜梭菌引起的气性坏疽。"},{"q":"一患者因咳嗽、咯血就诊，痰涂片染色镜检为结核分枝杆菌阳性。请问该菌应采用的染色方法是","o":["革兰染色","复红染色","棉兰染色","抗酸染色","墨汁染色"],"a":3,"e":"结核分枝杆菌细胞壁富含分枝菌酸，着色后不易被盐酸乙醇脱色，须用抗酸染色，阳性菌呈红色。"},{"q":"李某，男，60岁。上午6时到医院就诊，主诉在头天晚上18时左右食用羊肉火锅，4小时后出现腹痛腹泻症状。至就诊时，腹泻4～5次，尿液呈现深红色，肾叩痛，体温38℃；给予补液及抗生素治疗。8时许，患者腹痛加剧，手脚发麻，颈项僵直；9时30分抢救无效死亡。当日下午尸体迅速肿胀，颜面呈现紫褐色。晚5时解剖时呈巨人观。该患者的死亡可能是哪种疾病造成的","o":["金黄色葡萄球菌感染","甲型溶血性链球菌感染","结核分枝杆菌感染","肉毒梭菌感染","产气荚膜梭菌感染"],"a":4,"e":"产气荚膜梭菌α毒素为磷脂酶C，溶解红细胞和血管内皮，引起溶血、组织坏死和产气，故死后尸体迅速肿胀呈巨人观。"},{"q":"某男性游客，在东南亚旅游因天热饮用不洁河水后半日，呕吐并腹泻6～7次，排泄物呈米泔水样物，外观呈脱水状。怀疑可能感染了霍乱弧菌，应采用的检查方法是","o":["血液检查","排泄物行细菌培养","排泄物直接涂片观察","排泄物行乳糖发酵试验","悬滴法镜下观察排泄物中细菌动力"],"a":4,"e":"霍乱弧菌有单鞭毛、运动活泼，取排泄物做悬滴法暗视野观察，见鱼群样穿梭运动即可初步诊断。"},{"q":"患者，男，35岁，一周前从东南亚入境，3天前因突然剧烈呕吐、腹泻而入院。腹泻物呈米泔样，便检发现穿梭状运动的细菌。请问致病菌可能是","o":["肠侵袭性大肠埃希菌","伤寒沙门菌","变形杆菌","猪霍乱沙门菌","霍乱弧菌"],"a":4,"e":"米泔水样腹泻、剧烈呕吐，粪便中见穿梭运动的细菌，是霍乱弧菌经污染水传播的典型表现。"},{"q":"对某腹泻患者进行粪便培养，可疑菌落镜检到革兰染色阴性中等大小的杆菌，在半固体培养基中扩散生长。由此可推断该菌具有的结构为","o":["菌毛","荚膜","性菌毛","鞭毛","芽孢"],"a":3,"e":"有鞭毛的细菌在半固体培养基中沿穿刺线向四周扩散，呈羽毛状或云雾状生长；无鞭毛者仅沿穿刺线生长。"},{"q":"一位38岁男性旅游者从非洲归来，突发疾病，恶心、呕吐、腹泻。去医院就诊，常规镜检可见黏液和少许红细胞、白细胞。取粪便或早期培养物涂片作革兰染色镜检，可见革兰阴性弧菌。悬滴检查或暗视野显微镜检，可见运动活泼呈穿梭状的弧菌。该旅游者可能感染","o":["霍乱弧菌","破伤风梭菌","肠产毒性大肠埃希菌","福氏志贺菌","伤寒沙门菌"],"a":0,"e":"革兰阴性弧菌、悬滴见穿梭运动，结合腹泻呕吐，符合霍乱弧菌感染；该菌为甲类传染病的病原。"},{"q":"患者，男，22岁，因高热、咳嗽5天急诊入院。患者5天前洗澡受凉后出现寒战，体温高达40℃，伴咳嗽、咳痰，痰少呈铁锈色，无痰中带血，无胸痛。口服先锋霉素Ⅵ及止咳、退热剂3天后不见好转，体温仍波动于38、5～40℃。查体：急性热病容，神志清楚，无皮疹，浅表淋巴结无肿大，巩膜无黄染，咽（－），气管居中，左中上肺叩浊音，语颤增强，可闻湿性啰音，叩诊心界不大，心率100次/min，律齐，无杂音，腹平软，肝脾未及，病理反射未引出。实验室检查：Hb 140g/L，WBC 12×109/L，N 82%，L 18%，PLT 180×109/L；尿常规（－）；粪便常规（－）。初步诊断为大叶性肺炎。该病原体的主要致病物质是","o":["荚膜","脂质","鞭毛","内毒素","菌毛"],"a":0,"e":"肺炎链球菌的荚膜多糖具有抗吞噬作用，是其主要毒力因子；失去荚膜后细菌易被清除，毒力显著减弱。"},{"q":"患儿，女，3岁。持续性发热，腹泻，不对称性麻痹，右下肢肌力Ⅰ级，腱反射消失，病理征阴性；60天后残留麻痹，肌肉萎肌肉萎缩、腱反射减弱或消失，无病理征。该患儿最可能患的疾病是","o":["无菌性脑膜炎","流行性脑脊髓膜炎","新型隐球菌脑膜炎","流行性乙型脑炎","脊髓灰质炎"],"a":4,"e":"脊髓灰质炎病毒侵犯脊髓前角运动神经元，引起不对称性弛缓性麻痹，感觉正常，遗留肌肉萎缩和腱反射消失。"},{"q":"1986年，我国某地曾发生戊型肝炎的大流行。导致该病的病原体传播和流行的主要方式是","o":["粪-口途径","蚊虫叮咬","直接接触","性传播","血液和血制品"],"a":0,"e":"戊型肝炎病毒主要经粪-口途径传播，污染水源可引起大流行，我国新疆曾发生世界最大规模暴发。"},{"q":"患者，男，25岁，广州籍民工，因持续发热10天入院。主诉12天前低烧，后体温逐渐升高持续39～40.2℃，腹部饱胀，呕吐，腹泻，肝肋下触及1cm，脾肋下触及2cm。血常规：白细胞3.1×109/L。对该患者进行进一步诊断和治疗方案，哪项是不正确的","o":["肥达试验进一步确诊","进行血液或粪便培养","静脉滴注谷氨酸或精氨酸","及时补液，抗菌治疗","标本分离物接种于肠道选择性培养基"],"a":2,"e":"伤寒治疗应补液并选用敏感抗菌药物，谷氨酸、精氨酸用于肝性脑病，对肠热症无治疗作用。"},{"q":"患者，男，15岁，学生。3天前突然高热达39℃，伴发冷和寒战，同时出现剧烈头痛，频繁呕吐，呈喷射性，吐出食物和胆汁，无上腹部不适，进食少，二便正常。查体见皮肤散在少量出血点和脑膜刺激征。既往体健，无胃病和结核病史，无药物过敏史，所在学校有类似患者发生。取淤斑涂片镜检可见G－双球菌。临床诊断为流行性脑脊髓膜炎。建议首选的治疗药物是","o":["青霉素G","磺胺药物","红霉素","核苷类似物","阿德福韦"],"a":0,"e":"脑膜炎奈瑟菌对青霉素敏感，流行性脑脊髓膜炎治疗首选青霉素G，过敏者可改用红霉素。"},{"q":"20岁在校大学生，寒假前往北方某地游玩，突发头痛、恶心呕吐，伴有腹部痉挛性疼痛和水样便，无发热。电镜下粪便中可见大量球形病毒颗粒，具有双层衣壳，形似车轮状。对于该病毒的特性描述正确的是","o":["基因组分11个节段","不会引起动物腹泻","胰酶作用可使其感染性消失","致病机制是导致肠黏膜出血性坏死","目前无有效疫苗加以预防"],"a":0,"e":"轮状病毒基因组为双链RNA，分11个节段，电镜下呈车轮状，是婴幼儿重症腹泻最常见的病原体。"},{"q":"患者，男，65岁。两周前体检发现肝酶升高，约为正常上限的三倍，无黄疸，肝脾无肿大，无门脉高压。自诉既往无异常。否认酗酒或吸毒，没有正在服用其它药物。否认黄疸病史。45岁时曾因胃溃疡出血住院，手术治疗，输血4U；无并发症，无复发。有乙肝疫苗接种史。其它未发现异常。造成其肝功能检查异常最有可能的病原体是","o":["HAV","HBV","HCV","HDV","HEV"],"a":2,"e":"患者有输血史，无其他肝炎危险因素，肝酶升高而无黄疸，符合HCV感染易于慢性化的特点。"},{"q":"某地一幼儿园通过采集咽拭子标本及粪便标本，进行RT-PCR病毒核酸筛查发现一例脊髓灰质炎隐性感染病例。对该幼儿园其他儿童，可采取的预防脊髓灰质炎的特异性措施是","o":["注射抗生素","注射胎盘球蛋白或丙种球蛋白","服用脊髓灰质炎减毒活疫苗","注射抗病毒药物","消毒患儿排泄物，严格水和饮食卫生管理"],"a":2,"e":"脊髓灰质炎的特异性预防是口服减毒活疫苗，可刺激肠道产生分泌型IgA并形成群体免疫；抗生素和丙种球蛋白无特异性。"},{"q":"患者，男，75岁，多年高血压及糖尿病史。脑血管意外后卧床2月余，近期出现尿路感染表现，但抗菌治疗无效。中段尿接种到沙保培养基，菌落乳白色奶油样，镜检圆形或卵圆形，有芽生孢子。以下药物可以选择的是","o":["氨苄西林","阿莫西林","苯唑西林","氟康唑","氧氟沙星"],"a":3,"e":"长期卧床、抗菌治疗无效的尿路感染，沙保培养基长出乳白色酵母样菌落，提示白念珠菌，应选用氟康唑。"},{"q":"患儿，男，13个月。发热3天，突发阵发性全身性抽搐，频繁呕吐，烦躁，外周血白细胞数正常，无动物接触史。其乳母近期曾患“龈口炎”。该患儿最可能的诊断是","o":["流行性乙型脑炎","巨细胞病毒性脑炎","流行性脑脊髓膜炎","森林脑炎","单纯疱疹性脑炎"],"a":4,"e":"乳母近期患疱疹性龈口炎，患儿发热、抽搐、呕吐，符合HSV-1经密切接触传播引起的单纯疱疹性脑炎。"},{"q":"患儿，女，12岁，学生。因外阴瘙痒、分泌物增多1个月余，加重2周来我科门诊就诊。查体：外阴、阴阜可见对称性片状红斑，境界清楚，边缘可见散在红色丘疹。外阴分泌物多，实验室检查：取外阴阴道口分泌物，经10%KOH压片直接镜检，可见如图所示微生物。该患儿最可能感染的病原体是","o":["螺旋体","细菌","真菌","支原体","衣原体"],"a":2,"e":"官方题库缺失图片"},{"q":"患者，男，30岁，海南人。10月22～25日突然出现畏寒、发热，体温38、5℃，伴有头痛、眼眶痛及眼结膜充血。自10月25日起病情突然加重，体温39℃，皮肤出现大片紫癜及瘀斑，并出现黑便，粪便潜血试验阳性，血常规显示血小板数目为10×109/L，尿常规正常。该患者最可能感染的病原体是","o":["登革病毒","汉坦病毒","钩端螺旋体","沙门氏菌","脑膜炎奈瑟菌"],"a":3,"e":"官方答案为【沙门氏菌】，但依据教材，正确答案为【登革病毒】。海南10月为登革热流行季节，高热、头痛、眼眶痛、结膜充血伴血小板显著减少及皮肤大片紫癜瘀斑，符合登革出血热。"},{"q":"患者，女，50岁。高热、剧烈头痛、肌肉酸痛4天，皮疹1天入院。查体见患者眼结膜及面部充血，颈部有直径大约3～4mm斑丘疹。外斐反应（变形杆菌OX19）效价为1∶320。引起该病的病原体可能是","o":["贝纳柯克斯体","普氏立克次体","汉塞巴通体","汉坦病毒","恙虫病东方体"],"a":1,"e":"外斐反应OX19效价1∶320而OXK阴性，结合高热、剧烈头痛、肌痛和皮疹，符合普氏立克次体引起的流行性斑疹伤寒。"},{"q":"一成年男性，25岁，未婚，在出国体检中检出HIV抗体阳性。经询问，自认为身体无任何异常，否认吸毒史、同性恋史，但在两年前与几位女网友有过几次无防护性行为。关于该病例说法错误的是","o":["该患者可能处于无症状潜伏期","如不及时治疗可能发展为AIDS期","该患者血中的病毒量可能不高","该患者目前很难检出HIV p24抗原阳性","该患者有可能曾感染了HIV，但现已痊愈"],"a":4,"e":"HIV抗体阳性且无任何症状，提示可能处于无症状潜伏期，病毒低水平复制；HIV感染不能自愈，抗体终身阳性。"},{"q":"某5个月婴儿，便秘、头颈部肌肉软弱、吮乳无力、吞咽困难入院。查：眼睑下垂，全身肌张力减退。入院后多项检查提示“婴儿肉毒病”。引起此病的病原菌","o":["在有氧和无氧环境中都能生长","菌体内缺少过氧化物酶","属于自养菌范畴","通过光合作用获得能量","最适生长温度为10～20℃"],"a":1,"e":"肉毒梭菌为专性厌氧菌，缺乏过氧化氢酶和过氧化物酶，不能分解有毒氧基团，在有氧环境中不能生长。"},{"q":"患者，男，有不洁性交史。2个月前出现生殖器皮肤的无痛性溃疡，1个月后自然愈合。近日出现全身皮肤红疹，伴有淋巴结肿大。该患者可能患有","o":["猩红热","梅毒","麻疹","性病淋巴肉芽肿","风疹"],"a":1,"e":"无痛性硬下疳自愈后出现全身梅毒疹及淋巴结肿大，符合梅毒螺旋体感染由Ⅰ期进入Ⅱ期的表现。"},{"q":"患者，男，24岁。一天前突然出现腹泻。开始几次为黄色稀便，后转为白色米泔水样便，约每小时一次，无脓血便。无明显腹痛，无里急后重，无恶心、发热、头痛。几小时前，尿量明显减少，无腰痛。查体：体温35℃，血压80/50mmHg，脉搏110次/min；眼睑及双下肢无水肿，腹软，无压痛反跳痛，肾区无压痛、叩痛。引起该病的病原菌生化反应特点是","o":["吲哚试验阳性","尿素酶试验阳性","硫化氢试验阳性","分解葡萄糖产酸产气","枸橼酸盐利用试验阳性"],"a":0,"e":"白色米泔水样便、无腹痛里急后重、重度脱水，符合霍乱；霍乱弧菌能分解色氨酸生成吲哚，吲哚试验阳性。"},{"q":"患儿，男，8岁。发热伴皮疹5天，最先在前躯干部出现斑丘疹或水疱疹，后迅速向全身发展，呈向心性分布。最可能的诊断是","o":["麻疹","唇疱疹","斑疹伤寒","水痘","猩红热"],"a":3,"e":"皮疹先见于躯干、呈向心性分布，由斑丘疹迅速转为水疱疹，是水痘-带状疱疹病毒原发感染引起的水痘。"},{"q":"患者，男，26岁，军官，参加抗洪抢险，天气酷暑炎热，口渴难忍，喝了老百姓送来的矿泉水，2小时后剧烈腹部绞痛，水样便腹泻伴呕吐4次，继之出现米泔水样便。查体：疲倦面容，皮肤、唇舌干燥，眼窝深陷。血压53/37mmHg。取呕吐物和米泔水样便悬滴法镜检，见鱼群样细菌穿梭样运动。病原体可能为","o":["螺旋体","病毒","真菌","细菌","立克次体"],"a":3,"e":"抗洪后饮生水，剧烈腹泻呈米泔水样，悬滴见鱼群样穿梭运动，病原体为霍乱弧菌，属细菌。"},{"q":"某肝炎患者，血清学检查结果为：抗HAV IgM（－），抗HBsAb（＋），抗HCV-IgG（＋），抗HDV-IgM（－），抗HEV-IgM（－）。最可能感染的病原体是","o":["甲型肝炎病毒","乙型肝炎病毒","丙型肝炎病毒","丁型肝炎病毒","戊型肝炎病毒"],"a":2,"e":"抗-HCV-IgG阳性而其他肝炎病毒标志阴性，抗-HBs阳性为疫苗接种所致，提示丙型肝炎病毒感染。"},{"q":"患儿5岁，近来活动减少，乏力、食欲减退、盗汗。胸透见右肺上叶下部片状阴影，右肺门淋巴结肿大，应考虑诊断为","o":["小叶性肺炎","原发性肺结核病","支原体肺炎","病毒性肺炎","干酪样肺炎"],"a":1,"e":"儿童低热盗汗，X线见原发病灶与肺门淋巴结肿大构成的哑铃状阴影，是原发性肺结核病的原发综合征。"},{"q":"一新生儿室暴发脓毒血症，脓汁标本经涂片、革兰染色镜检发现大量葡萄球菌。为确定该菌是否有致病力，应检查","o":["血浆凝固酶","触酶","DNA聚合酶","尿素酶","磷酸酯酶"],"a":0,"e":"血浆凝固酶是鉴别金黄色葡萄球菌致病力的重要指标，凝固酶阳性者能凝固血浆、抵抗吞噬，致病力强。"},{"q":"患者，女，33岁，有吸毒史，近2年来反复复发带状疱疹5次。导致带状疱疹反复发作的最大原因可能是","o":["恶性肿瘤的感染导致的免疫力下降","疱疹病毒感染引起的免疫力低下","过度劳累导致的免疫力低下","HIV感染导致的免疫力低下","营养不良导致的免疫力低下"],"a":3,"e":"有吸毒史者反复发生带状疱疹，提示细胞免疫严重受损，HIV感染是最可能的原因，HIV破坏CD4+T细胞。"},{"q":"患儿，女，1岁，咳嗽1月、发热3天入院。体温最高39℃，伴咳嗽、干咳、气促、胸痛，输青霉素、头孢曲松等药物6天，无缓解。查体：咽充血，右肺呼吸音粗，左肺下呼吸音减低。诊断为支原体肺炎。下列哪项不是该病原体的致病因素","o":["顶端结构的P1蛋白","过氧化氢等代谢产物","超抗原作用","微荚膜","内毒素"],"a":4,"e":"支原体无细胞壁、无内毒素，其致病因素包括P1黏附蛋白、过氧化氢等代谢产物、超抗原和微荚膜。"},{"q":"一青年近3日咳嗽，高热39℃，铁锈色痰，WBC 18.5×109/L，X线胸片发现右肺中叶有大片阴影。临床诊断为大叶性肺炎，该病致病菌是","o":["肺炎杆菌","肺炎链球菌","肺炎衣原体","肺炎支原体","嗜肺军团菌"],"a":1,"e":"青壮年铁锈色痰、肺叶大片实变伴白细胞升高，是肺炎链球菌引起的大叶性肺炎，该菌为革兰阳性有荚膜双球菌。"},{"q":"一患者，近来突然出现神经兴奋性增高，吞咽、饮水，甚至听到流水声等轻微刺激均可引起痉挛。该患者最可能罹患的疾病是","o":["破伤风","鼠疫","肉毒中毒","博尔纳病","狂犬病"],"a":4,"e":"狂犬病病毒嗜神经，表现为恐水、吞咽及饮水时咽喉肌痉挛，甚至听到流水声即诱发痉挛，病死率近100%。"},{"q":"患者，男，46岁，务农。入院前半个月，患者打赤脚在地里挖荸荠，当时不慎损伤右足大脚趾皮肤，但未作处理，伤口自行愈合。因乏力、头晕、头痛、咀嚼无力、反射亢进、肌肉牵拉、抽搐及强直、张口不便，入院治疗。体温38.5℃，外周血白细胞13×109/L。初步怀疑该男子是由哪种病原体感染致病","o":["产气荚膜梭菌","破伤风梭菌","肉毒梭菌","炭疽芽孢杆菌","麻风分枝杆菌"],"a":1,"e":"破伤风梭菌芽胞经泥土污染的伤口侵入，在厌氧环境繁殖产毒，引起牙关紧闭、苦笑面容和全身肌肉强直痉挛。"},{"q":"患者，女，58岁。进食自制豆豉后3天，觉头晕、复视、乏力、眼睑下垂、吞咽困难、呕吐、气短、腹胀、便秘、尿潴留等，在当地治疗无效，上述症状加重，并出现全身瘫痪，急转院治疗。查体：言语困难、眼睑下垂、眼球水平移动困难，双瞳孔直径8mm，光反射极迟钝，颈软，心肺听诊无异常，肠鸣音减弱。初步诊断该患者是","o":["风湿热","毒性休克综合征","食物肉毒中毒","破伤风","炭疽"],"a":2,"e":"进食自制豆豉后出现眼睑下垂、复视、吞咽困难及弛缓性瘫痪，是肉毒毒素阻断乙酰胆碱释放所致食物肉毒中毒。"},{"q":"患者，高热，剧烈头痛，肌肉酸痛，入院。经实验室检查诊断该病人为立克次体感染。协助诊断立克次体病的交叉凝集试验是","o":["反向间接血凝试验","正向间接血凝试验","冷凝集试验","外斐反应","肥达试验"],"a":3,"e":"立克次体与变形杆菌某些菌株有共同抗原，用OX19、OX2、OXK代替立克次体抗原检测抗体，称外斐反应。"},{"q":"某患者急起畏寒、高热持续3天，头痛剧烈、全身酸痛、乏力，伴咽痛、干咳（无痰）等呼吸道症状，以及呕吐、腹泻等胃肠道症状。患者所在地近期有H3N2流行感冒的流行。血常规检查显示白细胞总数不高。如初步诊断为流感，可采用的血清学检测方法不包括","o":["ELISA试验","血凝抑制试验","中和试验","血凝试验","胶体金标记免疫层析法"],"a":3,"e":"流感血清学诊断常用ELISA、血凝抑制试验、中和试验和胶体金免疫层析法；血凝试验用于检测病毒，不用于检测血清抗体。"},{"q":"患儿，男，7岁，突起高热、头痛、呕吐及意识障碍，脑膜刺激征阳性，血清学检查显示乙型脑炎病毒IgM（＋）。对于该病特点的描述，正确的是","o":["患者及隐性感染者为主要传染源","库蚊为传播媒介和储存宿主","绝大多数表现为显性感染","绝大多数患者可出现中枢神经系统的症状","不易获得牢固的免疫力"],"a":1,"e":"乙脑病毒经蚊叮咬传播，库蚊既是传播媒介又是储存宿主，可带毒越冬并经卵传代；人感染后多为隐性感染。"},{"q":"患者，女，65岁。每日口服泼尼松15～30mg治疗膝关节肿痛，5个月后于颈部及腹股沟见1cm×2cm左右红斑各一块，其上散在丘疹；1年后皮损增多并融合，红斑上覆有鳞屑，取鳞屑及结痂经棉蓝染色可见大量有隔菌丝，棍棒状大分子孢子及散在小分生孢子，沙保培养基上生长出产生红色色素的丝状菌落。该患者最可能感染的真菌是","o":["石膏样小孢子菌","絮状表皮癣菌","红色毛癣菌","铁锈色小孢子菌","石膏样毛癣菌"],"a":2,"e":"长期用糖皮质激素者出现体癣样皮损，沙保培养基长出产生红色色素的丝状菌落，是红色毛癣菌的特征。"},{"q":"某患者是一名羊毛加工者，2周前突发高热、寒战，3日后发热消退，然后再次出现高烧和寒战，随后出现肝脾大、腹泻和关节疼痛，革兰染色可见阴性短小杆菌，该患者可能感染的病原体是","o":["肺炎链球菌","沙门氏菌","霍乱弧菌","布鲁氏菌","大肠埃希菌"],"a":3,"e":"羊毛加工者接触病畜，出现波状热、肝脾大、腹泻和关节痛，血中见革兰阴性短小杆菌，符合布鲁氏菌感染。"},{"q":"患者，男，24岁，有不洁性接触史，因近2日尿急、尿频、排尿刺痛而来院就诊。查体见尿道口有白色脓性分泌物。分泌物涂片染色，镜下见到G－成双排列的球菌。该患感染可能是由哪种细菌引起","o":["肺炎链球菌","淋病奈瑟菌","葡萄球菌","链球菌","脑膜炎奈瑟菌"],"a":1,"e":"不洁性接触后尿痛、尿道口脓性分泌物，涂片见中性粒细胞内革兰阴性双球菌，是淋病奈瑟菌感染。"},{"q":"患儿，女，8岁。咽痛、干咳、胸痛、发热3天，体温38、5℃，刺激性咳嗽明显。查体：右肺呼吸音低，无啰音。血常规：白细胞9.0 × 109/L，中性粒细胞65％。X线检查显示左下肺薄片状阴影。冷凝集试验结果阳性。最可能的诊断为","o":["腺病毒肺炎","呼吸道合胞病毒肺炎","肺炎支原体肺炎","金黄色葡萄球菌肺炎","肺炎链球菌肺炎"],"a":2,"e":"学龄儿童刺激性干咳、肺部体征轻而X线有浸润影，冷凝集试验阳性，符合肺炎支原体肺炎。"},{"q":"患者，28岁，因足底外伤，继而发热、惊厥、牙关紧闭呈苦笑面容入院，诊断为破伤风。引起上述症状的破伤风梭菌具有诊断意义的特殊结构是","o":["芽孢","菌毛","鞭毛","荚膜","性菌毛"],"a":0,"e":"破伤风梭菌芽胞呈圆形、位于菌体顶端，使菌体呈鼓槌状；芽胞抵抗力强，是诊断和消毒灭菌的重要依据。"},{"q":"某高校一大学生在秋冬季节与几位朋友到我国中西部几个城市旅游，突然有一天感到不适，出现恶心、呕吐症状，之后又出现腹部绞痛、水样腹泻，但没有发热症状。以下病毒中，最可能引起该大学生疾病的病原是","o":["轮状病毒","腺病毒","星状病毒","杯状病毒","肠道病毒"],"a":3,"e":"秋冬季成人突发呕吐、水样腹泻而无发热，符合杯状病毒（诺如病毒）引起的急性胃肠炎，常呈暴发流行。"},{"q":"某幼儿园，多名儿童相继出现低热、咳嗽等感冒症状，严重者出现阵发性痉挛性咳嗽，伴有呼吸困难、发绀等症状，咳时常呈鸡鸣样吼声。最可能感染的病原体是","o":["流感病毒","结核分枝杆菌","大肠埃希菌","百日咳鲍特菌","麻疹病毒"],"a":3,"e":"幼儿园儿童低热咳嗽后出现阵发性痉挛性咳嗽、鸡鸣样吼声和发绀，是百日咳鲍特菌引起的百日咳。"},{"q":"患儿，男，12天龄，出生体重1、5kg。患儿早产（孕7个月），并诊断为：先天性白内障、血小板减少、听觉诱发电位平直、无波形（可疑中枢性耳聋）、免疫性溶血、新生儿肺炎、病毒性脑炎等。其母亲，28岁，查出怀孕前3天发热，伴出红色斑丘疹，医院诊断为荨麻疹。怀孕7个月产下双胞胎，一胎死亡。该患儿胎内最可能感染的病原体是","o":["麻疹病毒","水痘-带状疱疹病毒","风疹病毒","柯萨奇病毒","普氏立克次体"],"a":2,"e":"孕早期感染风疹病毒可经胎盘垂直传播，引起先天性白内障、耳聋、血小板减少和心脏畸形等先天性风疹综合征。"},{"q":"患儿，男，出生63天。自出生第3天起出现黄疸，第10天左右黄疸基本消退，但1个月前又出现明显黄疸，精神、食欲尚可，无其他明显症状。其黄疸最可能的原因是","o":["生理性黄疸","甲型肝炎病毒感染","乙型肝炎病毒感染","黄病毒感染","人巨细胞病毒感染"],"a":4,"e":"新生儿期出现黄疸、消退后再次加重，肝功能轻度异常而一般情况好，符合人巨细胞病毒先天性感染。"},{"q":"患者，男，35岁。发热5天，最高体温40℃，急性重病容，酒醉貌，少尿，初步诊断为流行性出血热。以下有助于诊断的实验室检查不包括","o":["白细胞计数增高","血小板减少","血液浓缩","蛋白尿","小三阳"],"a":4,"e":"流行性出血热常见白细胞升高、血小板减少、血液浓缩和蛋白尿；小三阳为乙肝标志，与本诊断无关。"},{"q":"患儿，女，10岁。咽痛、咳嗽、发热后15天出现全身水肿，尿量减少，血压157/98mmHg。血常规：血红蛋白125g/L，白细胞5.7×109/L。尿常规：尿蛋白（＋），红细胞（＋＋＋＋），白细胞0个/HP，管型0个/HP。此病症由何种病原体感染所致","o":["金黄色葡萄球菌","A群链球菌","14型肺炎链球菌","脑膜炎奈瑟菌","淋球菌"],"a":1,"e":"咽炎后2周出现水肿、血尿、少尿和高血压，是A群链球菌感染后引起的急性肾小球肾炎。"},{"q":"患儿，男，5岁，因发热伴出疹症状就诊。其父母主诉小孩患“重感冒”多天并服用小儿感冒药多天，畏光。红色斑丘疹从患儿的耳后、前额、颈部扩散到身体的其他部分，部分部位皮疹变暗。查体发现该患儿还患有细支气管炎。尿检和颊部疹子刮取物镜检发现包涵体和多核巨细胞，咽喉拭子常规细菌培养阴性，抗链球菌溶素O试验阴性。该患儿所患疾病最可能的是","o":["药疹","水痘","风疹","麻疹","猩红热"],"a":3,"e":"发热、畏光、结膜充血，皮疹自耳后颈部向躯干四肢蔓延，颊黏膜见包涵体和多核巨细胞，符合麻疹。"},{"q":"患者，男，20岁，在广东务工2年，10月22日起出现高热，头痛、乏力伴肌肉酸痛3天入院。查体：体温39℃，下肢及前胸皮肤可见较多红色斑丘疹，结膜充血。血常规示血小板轻度减少，肝肾功能正常。患者近半个月来无外出活动史和野生动物接触史，无外来亲友探访，未接触过发热病人。应进一步进行病原学和血清学检查的病原体是","o":["登革病毒","乙型脑炎病毒","森林脑炎病毒","钩端螺旋体","汉坦病毒"],"a":0,"e":"广东10月、高热头痛肌痛伴皮疹和血小板减少，无其他接触史，符合登革病毒经蚊传播引起的登革热。"},{"q":"患者，女，18岁，因“3天前饮食不洁，出现剧烈腹泻和呕吐，排泄物呈米泔水样”急诊入院。体温正常，皮肤干燥，眼窝内陷，请问致病菌可能是","o":["痢疾志贺菌","伤寒沙门菌","霍乱弧菌","副溶血性弧菌","肠产毒性大肠埃希菌"],"a":2,"e":"剧烈腹泻呕吐、米泔水样排泄物伴脱水，符合霍乱弧菌感染；副溶血性弧菌多表现为腹痛和血水样便。"},{"q":"患者，男，28岁。右大腿清创缝合术后6天，发热，局部伤口红肿，范围较大，疼痛明显。伤口局部见稀薄脓液，淡红色，量多，无异味。最可能感染的致病菌是","o":["大肠埃希菌","铜绿假单胞菌","溶血性链球菌","金黄色葡萄球菌","无芽孢厌氧菌"],"a":2,"e":"术后伤口红肿、稀薄淡红色脓液量多而无异味，是乙型溶血性链球菌感染的特点；金黄色葡萄球菌脓液稠厚呈黄色。"},{"q":"患者，女，30岁。月经期突发高热、呕吐、腹泻，并出现明显皮疹，紧急到医院就诊。主诉未接触不洁食物，近期也无外伤、手术史，个人生活习惯良好，但在月经期习惯使用月经塞。为确定该患者是否为金黄色葡萄球菌感染，最应该进行下列哪项检测","o":["革兰染色","药敏试验","甘露醇发酵实验","肥达反应","外斐反应"],"a":2,"e":"月经期使用月经塞者突发高热、皮疹、低血压，符合金黄色葡萄球菌毒性休克综合征。该菌分解甘露醇产酸，表皮葡萄球菌与腐生葡萄球菌均不分解，故甘露醇发酵试验可用于菌种鉴定。"},{"q":"一名45岁的农民张某，在耕田时被田间残破的生锈钉子刺伤右侧足心，立即到医院就诊，如果你是接诊医生，选择哪项处理程序","o":["止血、缝合、包扎、抗生素治疗","清创、缝合","注射百白破疫苗、清创扩创、抗生素治疗","注射破伤风抗毒素、清创扩创、抗生素治疗","注射百白破疫苗及破伤风抗毒素、清创扩创、抗生素治疗"],"a":3,"e":"深部污染的刺伤应立即注射破伤风抗毒素中和游离痉挛毒素，同时清创扩创、用3%过氧化氢冲洗并配合抗生素杀灭繁殖体。受伤后接种疫苗不能立即产生保护性抗体，故不作首要处理。"},{"q":"患儿，女，10 岁。右眼眶周红斑、鳞屑10天。查体见右眶周有约5cm×6cm 大小红斑，红斑表面可见散在黄色小脓疱及白色的鳞屑。家中长期养狗。用胶带粘取病变部位鳞屑，拟进行显微镜观察以初步诊断，观察前对鳞屑的处理方法是","o":["高压蒸汽灭菌","紫外线照射30分钟","80℃加热30分钟","10% KOH微加热","10% H2SO4 微加热"],"a":3,"e":"含角质的鳞屑、病发或甲屑标本先用10%KOH微加热溶解角质，再直接镜检孢子或菌丝，是癣菌病的初步诊断方法。加热只软化角质，不破坏真菌结构。"},{"q":"患者，男，15岁。持续低热3天，同时4天前颜面部出现充血性斑丘疹，疹间皮肤正常，可见皮疹融合，就诊时皮疹消退，无色素沉着。双侧颊黏膜光滑，耳后、枕后、颈部可触及淋巴结增大，偶有咳嗽，无流泪症状。该患者最可能的诊断是","o":["风疹","麻疹","猩红热","伤寒","莱姆病"],"a":0,"e":"最可能为风疹。风疹皮疹为充血性斑丘疹，消退后不留色素沉着，伴耳后、枕后及颈部淋巴结肿大；麻疹退疹后有色素沉着和糠麸样脱屑，可资鉴别。"},{"q":"成年男性，因被流浪猫抓伤小腿（伤口很深）而来到社区医院就诊。对该病例不恰当的处理方式是","o":["应立即对伤口深部进行灌流清洗，并用碘酊消毒","可联合使用抗狂犬病免疫球蛋白","肌肉注射大剂量的青霉素","局部注射抗狂犬病病毒血清","接种狂犬病病毒灭活疫苗"],"a":2,"e":"狂犬病暴露后应冲洗伤口、碘酊消毒并接种灭活疫苗，深部严重伤口还需局部浸润抗狂犬病血清或免疫球蛋白。青霉素对狂犬病病毒无效，肌内注射大剂量青霉素属不当处理。"},{"q":"患者，男，65岁。因乏力、厌油、呕吐、腹胀及黄疸入院治疗，诊断为“急性乙型肝炎”。在其感染过程中，参与肝细胞损伤的免疫病理反应最可能包括","o":["Ⅰ型和Ⅱ型超敏反应","Ⅱ型和Ⅲ型超敏反应","Ⅰ型和Ⅳ型超敏反应","Ⅱ型和Ⅳ型超敏反应","Ⅰ型、Ⅱ型和Ⅲ型超敏反应"],"a":1,"e":"乙型肝炎的肝细胞损伤由免疫病理介导，效应T细胞杀伤带病毒抗原的肝细胞及抗体介导的细胞毒作用属Ⅱ型超敏反应，抗原抗体复合物沉积于血管壁属Ⅲ型超敏反应。Ⅰ型和Ⅳ型不参与该过程。"},{"q":"暴风雨过后，某岛上一位50岁的渔民和他的妻子出现腹泻症状，同岛其他人也有轻度腹泻。随后，渔民的妻子出现严重水样腹泻、呕吐，继而肾衰竭，呼吸和心脏功能衰竭。对她进行抗生素治疗和补液疗法效果很好。从患者粪便标本中分离到革兰阴性弧菌。最可能的病原体是下列哪一种","o":["空肠弯曲菌","肠炎沙门菌","福氏志贺菌","霍乱弧菌","幽门螺杆菌"],"a":3,"e":"最可能为霍乱弧菌。该菌肠毒素激活肠黏膜腺苷酸环化酶使cAMP升高，肠液大量分泌，出现剧烈水样腹泻、呕吐、脱水乃至肾衰竭，粪便分离出革兰阴性弧菌可支持诊断。"},{"q":"患者，女，16岁。左手食指因外伤发生伤口感染，感染灶局限，分泌物为金黄色脓液。进行细菌分离培养：血平板上菌落呈金黄色，周围出现完全透明的溶血环，凝固酶试验阳性。引起感染最可能的细菌是","o":["A群链球菌","表皮葡萄球菌","金黄色葡萄球菌","腐生葡萄球菌","肺炎链球菌"],"a":2,"e":"血平板菌落呈金黄色、周围完全透明溶血环、血浆凝固酶阳性，是金黄色葡萄球菌的典型特征。表皮与腐生葡萄球菌凝固酶阴性，A群链球菌菌落细小且触酶阴性。"},{"q":"一个5岁男孩因发烧、游走性关节炎和心肌炎而入院，该男孩出现严重的喉痛，伴发热。入院前两天，出现面部、颈部和四肢的无意识、无目的、不适当的运动，实验室检查显示白细胞增多，蛋白水平升高，血沉速度升高，常规血培养结果阴性，但患者血清中发现高滴度抗链球菌溶素O抗体。患者出现心脏损害的主要原因是","o":["链球菌溶素O介导的心脏组织的直接损伤","白喉毒素侵犯心肌细胞和神经细胞","破伤风痉挛毒素侵犯心瓣膜和神经细胞","由抗链球菌抗体与心瓣膜抗原结合引起的免疫损伤","细菌在心瓣膜上生长繁殖"],"a":3,"e":"该患儿为链球菌咽峡炎后风湿热。抗链球菌细胞壁M蛋白抗体与心肌抗原交叉反应引起Ⅱ型超敏反应，免疫复合物沉积血管基底膜引起Ⅲ型超敏反应，共同造成心肌和心瓣膜损伤。"},{"q":"自然灾害过后，当地农村断水断电，生活陷入困境。居民在饮用河水后，许多人出现恶心、呕吐和腹泻症状，排泄物呈“米泔水”样。经当地医疗机构检测后发现，该疾病是由一种可激活腺苷酸环化酶系统、导致cAMP水平增加的毒素引起的。可产生这种毒素的细菌是","o":["布鲁氏菌","伤寒沙门菌","志贺菌","大肠埃希菌","霍乱弧菌"],"a":4,"e":"最可能为霍乱弧菌。霍乱肠毒素激活肠黏膜上皮细胞腺苷酸环化酶，使细胞内cAMP升高，隐窝细胞分泌氯和碳酸氢根增加、绒毛吸收钠减少，导致米泔水样腹泻与呕吐。"},{"q":"患儿，女，3岁。一周前感冒，发热，3天后口腔黏膜起疱，破溃，疼痛。最可能的诊断是","o":["疱疹性龈口炎","流行性感冒","猩红热","水痘","麻疹"],"a":0,"e":"最可能为疱疹性龈口炎。HSV-1原发感染多见于儿童，表现为发热及口腔黏膜水疱、破溃疼痛；水痘皮疹呈向心性分批出现，麻疹有科氏斑，均与本例不符。"},{"q":"患儿，男，5岁。急性起病，发热、咳嗽，手掌、脚掌部、臀部及膝盖出现斑丘疹，皮疹周围有炎性红晕，疱内液体较少，口腔黏膜出现散在的疱疹，疼痛明显。同时伴有肌阵挛，急性迟缓性麻痹。患儿最可能感染的病原体是","o":["风疹病毒","恙虫病东方体","麻疹病毒","埃可病毒","新肠道病毒71型"],"a":4,"e":"最可能为新肠道病毒71型。手足口病伴肌阵挛、急性迟缓性麻痹提示EV-A71感染，该病毒除引起手、足、口、臀皮疹疱疹外，可并发脑干脑炎、无菌性脑膜炎和急性弛缓性麻痹。"},{"q":"患者，男，20岁，农民，高热、全身肌肉酸痛、乏力7天。查体：眼结膜充血，巩膜黄染，肝肋下1、5cm，腓肠肌压痛明显。尿蛋白（＋）。血清胆红素和丙氨酸转氨酶均明显升高。肥达反应O 1∶40、H 1∶80，钩体显微镜凝集试验1∶400。外斐反应OX2、OX19、OXK均小于1∶80。最可能的诊断是","o":["伤寒","钩端螺旋体病","甲型急性黄疸型病毒性肝炎","斑疹伤寒","流行性出血热"],"a":1,"e":"钩端螺旋体病。接触疫水后高热、腓肠肌压痛、结膜充血、黄疸，钩体显微镜凝集试验1:400阳性即可诊断；肥达反应效价低、外斐反应阴性，不支持伤寒与斑疹伤寒。"},{"q":"患者，女，24岁，药物流产10日后再次就诊，诉近几日白带增多，带血丝，有异味。妇检：子宫附件正常，扩阴器暴露阴道，见后穹隆部有豆腐渣样块状分泌物，宫颈口有少量血性黏液。分泌物涂片镜检发现如图所示病原体该病原体最可能为","o":["单细胞真菌","多细胞真菌","丝状真菌","支原体","沙眼衣原体"],"a":0,"e":"官方题库缺失图片"},{"q":"患者，女，22岁。入院前2周持续性发热，体温高达39～40℃，发热期间伴食欲缺乏。体检肝、脾略大，腹部见玫瑰疹。血白细胞3.5×109/L。肝功正常，血培养阴性，肥达试验结果：TO 1∶320，TH 1∶320，PA 1∶40，PB 1∶40。该患者最可能的诊断是","o":["病毒性肠胃炎","上呼吸道感染","细菌性痢疾","淋巴结炎","伤寒"],"a":4,"e":"最可能为伤寒。持续高热、玫瑰疹、肝脾大、白细胞减少，肥达试验O与H效价均达1:320，符合伤寒沙门菌感染；副伤寒抗体效价低可排除副伤寒。"},{"q":"患儿，男，2岁。因不对称下肢就诊。其母诉说患儿3个月前患持续性发热，头痛，腹泻，之后自然消失。查体示右下肢细短，软弱无力不能行走，右腿深部腱反射消失，但无感觉障碍。上肢活动正常，头部神经反射正常。肌电图（EMG）呈慢性部分神经切除改变，并伴有静脉肌肉异常自发活动。引起患儿疾病最可能的病原体是","o":["脊髓灰质炎病毒","脑膜炎奈瑟菌","新型隐球菌","流行性乙型脑炎病毒","埃可病毒"],"a":0,"e":"最可能为脊髓灰质炎病毒。患儿不对称下肢弛缓性麻痹、腱反射消失而无感觉障碍，提示脊髓前角运动神经元受损；该病毒经粪-口传播，麻痹后遗留肌肉萎缩。"},{"q":"某患者血液标本“二对半”的检测结果为：HBsAg（＋），抗-HBs（-），HBeAg（＋），抗-HBe（-），抗-HBc（＋）。最有可能的诊断是","o":["乙型肝炎潜伏期","乙型肝炎急性期","乙型肝炎恢复期","HBV病毒既往感染","接种过乙肝疫苗"],"a":1,"e":"HBsAg、HBeAg、抗-HBc同时阳性即大三阳，提示HBV复制活跃、传染性强，符合乙型肝炎急性期。抗-HBs为中和抗体，其阴性说明尚未产生免疫力，故非恢复期或疫苗接种后。"},{"q":"患儿，男，9岁，夏天玩耍时踩中生锈的铁钉被刺伤，铁钉穿透他的运动鞋，刺入他的右脚，但是他没有告诉父母，因为刺伤处出血很少，晚饭时就止住了。一个星期后，患儿开始喉咙痛；４天以后，患儿出现吞咽、说话、呼吸困难，同时出现肌肉痉挛，父母不得不带他去看医生，医生怀疑其为破伤风梭菌感染，并检测了其破伤风梭菌免疫球蛋白。医生询问其父母该患儿上次接种破伤风疫苗的时间，父母表示不知道。一周后患儿因为呼吸衰竭而死亡。病原体的基本特征是","o":["致病微生物，破伤风梭菌，是一种严格的厌氧菌","致病微生物，破伤风梭菌，是一种严格需氧菌","致病微生物，破伤风梭菌，产生一种非热稳定性的毒素","致病微生物，破伤风梭菌，产生芽孢，产生一种非热稳定性的毒素","致病微生物，破伤风梭菌，产生芽孢，是一种严格需氧菌，产生一种非热稳定性的毒素"],"a":3,"e":"破伤风梭菌为革兰阳性专性厌氧芽胞杆菌，芽胞位于菌体顶端使菌体呈鼓槌状。其痉挛毒素为外毒素，60～80℃30分钟即被破坏，属不耐热毒素；严格需氧的描述错误。"},{"q":"患儿5岁，发烧、咽痛、咳嗽5天急诊入院，免疫接种史不详。查体：咽后壁、腭弓和悬雍垂等处发现灰白色膜状物，用灭菌棉拭子不易擦掉。初步诊断为","o":["白喉","急性咽炎","病毒性咽炎","扁桃体炎","支气管炎"],"a":0,"e":"初步诊断为白喉。咽部灰白色假膜不易擦去，由白喉棒状杆菌在咽部繁殖并产生外毒素所致；假膜累及气道可致梗阻，毒素吸收入血引起心肌和周围神经损害。"},{"q":"某年秋季，某幼儿园出现轮状病毒性腹泻的流行，对于该病毒感染的防控措施不包括","o":["避免饮用未经煮沸的水","加强洗手","污染物消毒","注射丙种球蛋白","口服减毒活疫苗"],"a":3,"e":"轮状病毒经粪-口传播，防控以煮沸饮水、洗手、污染物消毒等切断传播途径和口服减毒活疫苗为主。注射丙种球蛋白属被动免疫，不是该病的常规防控措施。"},{"q":"患者一个月前感到疲劳、食欲减少、体重减轻、发热、咳嗽、痰带血丝。欲取痰标本涂片染色镜检，对该菌应采用的染色方法应该首选","o":["革兰氏染色","抗酸染色","棉兰染色","复红染色","墨汁染色"],"a":1,"e":"痰标本检查结核分枝杆菌首选抗酸染色。该菌细胞壁含分枝菌酸，与石炭酸复红牢固结合而不被盐酸乙醇脱色，镜检呈红色；革兰染色和墨汁染色均不能显示其抗酸性。"},{"q":"患儿，男，5岁，随母亲旅游时在外就餐，吃未煮透牛排之后，出现发烧、呕吐、剧烈腹痛、大便次数增加伴血便，同时血小板减少。判断其可能的细菌感染是","o":["伤寒沙门菌","鲍氏志贺菌","肠出血性大肠埃希菌","痢疾杆菌","霍乱弧菌"],"a":2,"e":"最可能为肠出血性大肠埃希菌。进食未煮透牛肉后发热、剧烈腹痛、血便并伴血小板减少，符合该菌所致感染；其志贺毒素可并发溶血性尿毒综合征，儿童多见。"},{"q":"2岁男孩，突然发热、呕吐及腹泻1天，排出大量水样便，其所在幼儿园也有数名幼儿出现类似症状，但教师中无类似病例。初步判断最可能的感染病原体是","o":["A组轮状病毒","肠侵袭性大肠埃希菌","痢疾志贺菌","柯萨奇病毒","诺如病毒"],"a":0,"e":"最可能为A组轮状病毒。2岁幼儿水样腹泻、呕吐伴发热，同园幼儿多人发病而教师无病例，符合轮状病毒胃肠炎；该病毒主要侵犯6个月至2岁婴幼儿，成人多已获免疫。"},{"q":"患者，男，30岁。3周前出现为尿道内不适，刺痛及烧灼感，并伴有不同程度的尿频、尿急、尿痛。尿道口轻度红肿并有浆液分泌物，附睾肿大，有触痛，分泌物镜检未见革兰阴性双球菌，最有可能是何种病原体感染","o":["沙眼衣原体","淋球菌","梅毒螺旋体","人巨细胞病毒","白假丝酵母菌"],"a":0,"e":"最可能为沙眼衣原体。尿道刺痛、浆液性分泌物伴附睾肿大，而淋球菌镜检阴性，符合非淋菌性尿道炎；沙眼衣原体血清型D～K侵犯男性生殖道，引起尿道炎、附睾炎和前列腺炎。"},{"q":"患儿，女，5岁，在当地一家快餐店参加生日聚会。约48小时后，她出现发热，剧烈腹痛伴血便，次日因为持续腹痛腹泻、少尿到急诊科就诊。最有可能导致该患儿患病的病原体是","o":["肠出血性大肠杆菌","伤寒沙门菌","肠致病型大肠埃希菌","葡萄球菌","志贺菌"],"a":0,"e":"最可能为肠出血性大肠杆菌。快餐店集体发病、剧烈腹痛伴血便及少尿，符合O157:H7感染；该菌产志贺毒素，可并发溶血性尿毒综合征导致急性肾衰竭。"},{"q":"患儿，男，7岁。肌阵挛抽动伴认知功能下降3月余，既往发育阶段各标志不明显，有认知功能损害。刚出生1个月时，曾患麻疹，很快痊愈。脑电图显示节律性活动。颅脑MRI检查显示大脑白质内不均匀的高信号。血常规白细胞数不高。该患儿最可能的诊断是","o":["海绵状脑病","流行性脑脊髓膜炎","流行性乙型脑炎","亚急性硬化性全脑炎","急性脑膜炎"],"a":3,"e":"最可能为亚急性硬化性全脑炎。麻疹病愈后数年出现肌阵挛、认知下降和脑电图节律性异常，是麻疹病毒持续感染所致；该病属慢发病毒感染，进行性加重，最终死亡。"},{"q":"一老年男性患有慢性基础疾病且行动不便，在中央空调房间内长期生活，出现了发热、寒战、头痛和肌肉痛的症状，伴有咳嗽、胸痛，全身症状明显，诊断为嗜肺军团菌感染，其感染的临床类型属于","o":["流感型","肺炎型","肺外感染型","菌血症","继发型"],"a":1,"e":"属肺炎型军团病。军团菌经中央空调气溶胶吸入，起病急骤，高热寒战、咳嗽胸痛伴多器官损害，X线示肺炎；流感样型即庞蒂亚克热症状轻，无肺炎征象。"},{"q":"一艾滋病患者，最近出现发热、咳嗽、胸闷等肺部感染症状。继发感染应优先考虑的最常见病原体是","o":["李斯特菌","巨细胞病毒","肺孢子菌","白假丝酵母菌","结核分枝杆菌"],"a":2,"e":"应优先考虑肺孢子菌。艾滋病患者CD4+T细胞明显减少，肺孢子菌肺炎是最常见的机会性感染，表现为发热、干咳和进行性呼吸困难；该菌经呼吸道吸入，在免疫缺陷者肺内大量增殖。"},{"q":"患儿，女，5岁，因间断咳嗽气喘2个月，加重1周就诊。查体：咽红充血，双肺呼吸音粗，可闻及痰鸣、喘鸣及中小湿啰音。胸片提示支气管肺炎。取呼吸道分泌物进行支原体培养，能分解葡萄糖，但不分解尿素及精氨酸；固体培养基培养3天，显微镜下可见“荷包蛋”样菌落。请问引起本病的病原体最可能是","o":["解脲脲原体","人型支原体","肺炎支原体","肺炎嗜衣原体","流感嗜血杆菌"],"a":2,"e":"最可能为肺炎支原体。该菌发酵葡萄糖，不分解尿素和精氨酸，固体培养呈荷包蛋样菌落，符合本例支气管肺炎的病原学特征；解脲脲原体分解尿素，人型支原体分解精氨酸。"},{"q":"患者，女，52岁，农民。因“咳嗽、胸闷、气喘进行性加重9个月”就诊。患者住房条件较差，近一个月其卧室堆放了大量未干透的稻草。经一系列检查，初步诊断为农民肺。农民肺的发病机制是","o":["吸入真菌孢子或菌丝引起的肺部致病真菌感染性疾病","吸入真菌孢子或菌丝引起的超敏反应性疾病","吸入真菌孢子或菌丝引起的真菌毒素中毒","吸入真菌孢子或菌丝引起的肺部条件致病真菌感染性疾病","细菌感染引起的肺炎"],"a":1,"e":"农民肺属真菌性超敏反应。反复吸入霉变谷草中的真菌孢子或菌丝后，经抗原抗体复合物和细胞免疫介导肺泡炎，属接触性超敏反应；并非真菌直接感染或毒素中毒。"},{"q":"患者，男，18岁。因发热14天、皮疹9天入院就诊，伴咽痛，按感冒治疗未见好转。查体：浅表淋巴结肿大，肝脾大，IgM异嗜性抗体阳性。最可能的诊断是","o":["肠热症","巨细胞病毒单核细胞增多症","链球菌咽峡炎","传染性单核细胞增多症","急性感染性淋巴细胞增多症"],"a":3,"e":"最可能为传染性单核细胞增多症。发热、咽痛、淋巴结及肝脾肿大伴异嗜性抗体阳性，是EB病毒感染后非特异性活化B细胞产生的抗体，可用于该病辅助诊断。"},{"q":"患者，男，75岁，以肺部感染及呼衰入院。患者发热、咳嗽、咳痰伴心悸、气短，双下肺湿啰音，痰为黄色、不易咳出。痰标本接种至沙保培养基35℃培养，菌落呈绒毛状，表面呈深绿色、烟绿色，背面淡黄色，棉兰染色可见分生孢子头短柱状，分生孢子梗壁光滑，带淡绿色，顶囊呈烧瓶状，小梗单层，分布在顶囊的上半部，分生孢子球形，绿色，有小刺。该患者可能感染的真菌是","o":["许兰毛癣菌","烟曲霉","放线菌","申克孢子丝菌","诺卡菌"],"a":1,"e":"最可能为烟曲霉。沙保培养基35℃长出深绿色绒毛状菌落，顶囊烧瓶状、小梗单层分布于顶囊上半部、孢子球形有小棘，为其典型形态；黄曲霉顶囊球形、小梗双层。"},{"q":"春季，一幼儿园数名儿童先后出现发热，流泪、流涕，眼结膜充血，咳嗽，面部、躯干及上肢皮肤呈米糠样斑丘疹。这些患儿最可能的诊断是","o":["风疹","麻疹","猩红热","伤寒","莱姆病"],"a":1,"e":"最可能为麻疹。发热及流泪、流涕、结膜充血、咳嗽等卡他症状后出现米糠样斑丘疹，符合麻疹；前驱期颊黏膜有科氏斑，皮疹自耳后颈部向躯干四肢蔓延。"},{"q":"患者，男，29岁。在婚检中检出HIV抗体阳性。经询问，否认外伤史、输血手术史、吸毒史等，但回忆在17岁时有过一次嫖娼史。自述平常身体无任何异样。经检测CD4＋T细胞600个/μl，外周血病毒拷贝数低于20拷贝数/ml。关于该病例说法错误的是","o":["该患者可以不用进行抗病毒治疗","该患者仍具有传染性","该患者可能是“长期不进展者”","该患者可以结婚并生下健康的孩子","该患者曾感染了HIV，但现已自愈"],"a":4,"e":"HIV感染不能自愈，病毒可终身潜伏于宿主细胞，故该说法错误。患者CD4+T细胞600个/μl、病毒载量极低且无症状，属长期不进展者，仍具传染性，可暂缓治疗并在母婴阻断下生育。"},{"q":"患者，女，20岁，个体户。反复头痛已半年，多处诊治，服药5～10日可减轻。近1个月来头痛加重，痛剧时伴恶心、呕吐。检查除颈稍抵抗、Kernig（＋）外，余无阳性征。腰穿CSF压力250mmH2O，细胞50×106/L，蛋白0、86g/L，按病毒性脑膜炎治疗2周无效。查血RPR1∶32，TPHA1∶2560。腰穿CSF230mmH2O，细胞70×106/L，蛋白1.02g/L，RPR1∶2，TPHA1∶1280。经青霉素治疗一疗程，头痛渐轻，最后消失出院。该患者患的疾病最可能为","o":["梅毒性脑膜炎","化脓性脑膜炎","结核性脑膜炎","隐球菌性脑膜炎","流脑"],"a":0,"e":"最可能为梅毒性脑膜炎。患者有头痛和脑膜刺激征，脑脊液压力升高、淋巴细胞增多，血与脑脊液RPR、TPHA均阳性，青霉素治疗有效；化脓性、结核性和隐球菌性脑膜炎无此血清学结果。"},{"q":"某建筑工地工人被掉下的钢筋扎入手臂，送入急诊室治疗，对伤口进行正确得当的处理后，收入院继续观察治疗。住院期间，为确诊该患者是否存在破伤风细菌的感染，实验室应采用的细菌培养基是","o":["罗氏培养基","吕氏培养基","庖肉培养基","双糖铁培养基","巧克力色培养基"],"a":2,"e":"破伤风梭菌为专性厌氧菌，分离培养应选庖肉培养基，并在液面加凡士林或液状石蜡隔绝空气。罗氏培养基用于结核分枝杆菌，吕氏血清斜面用于白喉棒状杆菌。"},{"q":"患儿，男，10岁。右足底被铁锈钉刺伤10天。突然出现张嘴困难，继之出现苦笑面容，角弓反张，声响及触碰患儿可诱发上述症状。患儿神志清楚，不发热。患儿所患疾病为","o":["毒血症","败血症","菌血症","脓血症","脓毒血症"],"a":0,"e":"所患疾病为毒血症。破伤风痉挛毒素在局部伤口产生后吸收入血，引起牙关紧闭、苦笑面容和角弓反张，而细菌不进入血流；败血症和菌血症均有病原菌入血。"},{"q":"患者，女，27岁。家里养一只小狗。患者因前额、颈部多发环状红斑14天来院就诊。皮肤专科检查：前额及颈部共四个黄豆至铜钱大小皮损，略呈圆形斑块，周围稍高起，中央较平坦，皮损边缘活跃，见有密集的红色小丘疹及领圈样鳞屑，中央皮肤淡红或正常肤色。真菌学检查：取皮损边缘鳞屑，10%KOH制片直接镜检可见如图所示结构，箭头所指结构为","o":["生殖菌丝","结节菌丝","球拍状菌丝","有隔菌丝","螺旋状菌丝"],"a":3,"e":"官方题库缺失图片"},{"q":"患者，男，40岁，一周前出现高热，维持在39、5～40℃，全身乏力，大便次数增多，每天5～6次。肥达反应：TO 1∶160，TH 1∶320，PA 1∶40，PB 1∶40。引起这种疾病的病原体可能是","o":["霍乱弧菌","伤寒沙门菌","克雷伯菌","福氏志贺菌","变形杆菌"],"a":1,"e":"最可能为伤寒沙门菌。持续高热、肝脾大，肥达反应O 1:160、H 1:320而副伤寒抗体阴性，符合伤寒；伤寒沙门菌属D群，含O抗原9、12和H抗原d。"},{"q":"患者，男，45岁。近半个月来尿道口轻度红肿，晨起有少许稀薄分泌物。淋球菌培养阴性，沙眼衣原体检查阴性。尿道口棉拭子取样接种支原体液体培养基培养，能分解精氨酸，不分解尿素。固体培养可见“油煎蛋”样菌落。最可能的病原体是","o":["人型支原体","解脲支原体","肺炎支原体","生殖支原体","发酵支原体"],"a":0,"e":"最可能为人型支原体。该菌分解精氨酸而不分解尿素，固体培养呈油煎蛋样菌落，可引起尿道炎和附睾炎；解脲脲原体分解尿素，肺炎支原体发酵葡萄糖。"},{"q":"两名大学生在路边摊食用臭豆腐48小时后，相继自觉乏力、头痛，继而出现复视、眼睑下垂、吞咽和说话困难，以及呼吸困难等症状，初步诊断引起患者此种症状的病原体是","o":["破伤风梭菌","产气荚膜梭菌","肉毒梭菌","艰难梭菌","炭疽杆菌"],"a":2,"e":"最可能为肉毒梭菌。进食臭豆腐后出现复视、眼睑下垂、吞咽及呼吸困难，为肉毒毒素所致弛缓性麻痹；该菌在厌氧条件下产生肉毒毒素，阻断胆碱能神经末梢释放乙酰胆碱。"},{"q":"患者，女，38岁。因发热、黄疸、腹胀、乏力入院，诊断为“急性甲型肝炎”。引起该病的病原体的主要传播途径是","o":["血液传播","消化道传播","呼吸道传播","密切接触传播","性接触传播"],"a":1,"e":"甲型肝炎病毒主要经消化道传播，通过污染的水、食物（如毛蚶）和食具引起散发或暴发流行。血液、性接触和母婴传播是乙型、丙型和丁型肝炎的主要传播途径。"},{"q":"患者，男，35岁。间歇性发热12天，高热和低热交替出现，高热时伴有头痛、乏力，最高体温39.5℃，无咳嗽。患者于两周前到牧区旅游，曾饮用未消毒的鲜牛奶，无蚊虫叮咬史。X光检查肺部未见异常。该病例的可能诊断是","o":["钩端螺旋体病","斑疹伤寒","布鲁菌病","肺结核","恙虫病"],"a":2,"e":"最可能为布鲁菌病。牧区旅游、饮用未消毒鲜牛奶后出现波浪状发热、头痛和乏力，符合布鲁菌感染；该菌为胞内寄生菌，经消化道和破损皮肤侵入，波浪热为其特征。"},{"q":"患者，35岁，发热5天，面部、前胸皮肤充血潮红，腋下见针尖样出血点，血常规示白细胞计数13.12×109/L，血小板计数39×109/L，肾功能检查尿素氮18.6mmol/L，血肌酐491.9mmol/L。该病例可诊断的疾病是","o":["急性肾小球肾炎","肾综合征出血热","肠热症","登革热","钩体病"],"a":1,"e":"诊断为肾综合征出血热。发热、面颈前胸潮红、腋下出血点，伴血小板减少和急性肾功能损害，符合汉坦病毒感染；该病毒经鼠类排泄物气溶胶等途径传播。"},{"q":"幼儿园刚放暑假，一名3岁男孩突然出现水样腹泻，伴有咽痛、咳嗽和轻度发热，无呕吐。最可能的感染病原体是","o":["G组轮状病毒","B组轮状病毒","肠道腺病毒","杯状病毒","柯萨奇病毒"],"a":2,"e":"最可能为肠道腺病毒。婴幼儿水样腹泻伴咽痛、咳嗽和低热而呕吐不明显，符合腺病毒胃肠炎；腺病毒40、41型经粪-口和呼吸道传播，腹泻时常伴呼吸道症状。"},{"q":"患者，男，20岁。乏力、低热、咳嗽月余，胸部X片显示在右肺上叶有炎性浸润灶，取痰标本抗酸染色阳性。最可能的诊断是","o":["肺脓肿","大叶性肺炎","葡萄球菌性肺炎","肺结核","肺癌"],"a":3,"e":"最可能为肺结核。低热、乏力、咳嗽月余，右上肺有炎性浸润灶，痰抗酸染色阳性，符合继发性肺结核；结核分枝杆菌抗酸染色呈红色，病变好发于上叶尖后段。"},{"q":"患者，女，高热，剧烈头痛，肌肉酸痛。入院检查，体格检查、外斐反应结果表明该病人为普氏立克次体感染。下列哪项为普氏立克次体感染的传播媒介","o":["人虱","鼠蚤","蚊子","蜱","恙螨"],"a":0,"e":"普氏立克次体引起流行性斑疹伤寒，病人是储存宿主和传染源，人虱（体虱）是传播媒介。立克次体随虱粪排出，经搔抓的皮肤破损处侵入人体。"},{"q":"某年秋季，山西某地连续报告流行性乙型脑炎病例数十例，病例呈散发，主要集中于农村地区，以下对该病的最主要预防措施是","o":["隔离乙脑感染病人","人群注射Sabin疫苗","人群注射Salk疫苗","对流行区幼猪进行疫苗接种","防鼠灭鼠"],"a":3,"e":"最主要预防措施是对流行区幼猪接种疫苗。乙脑病毒在猪与蚊之间循环，幼猪感染后病毒血症持续时间长、滴度高，是主要传染源和扩散宿主，切断该环节可控制流行。"},{"q":"患者，男，63岁，近半年来出现进行性发展的痴呆、肌痉挛、小脑共济失调、运动性失语，并迅速发展为半瘫、癫痫。该患者最终死于中枢神经系统功能衰竭。对于该病最可能的诊断是","o":["CJD","BSE","TME","FFI","CWD"],"a":0,"e":"最可能为CJD。中年患者迅速进展的痴呆、肌阵挛、共济失调，符合克雅病；该病由朊粒引起，属传染性海绵状脑病，症状出现后平均生存4～5个月。"},{"q":"患者，男，27岁，因心悸、严重头痛、疲劳、游走性关节痛以及周围神经根神经症状就医。自诉3个月前有过一次野营旅游，回来后腿上出现红疮，但他记忆中没被硬蜱叮咬过，红疮微微隆起，逐渐扩大形成一片圆形皮损，外缘鲜红，发热，直径大约5cm，约3周后消退。住院检查脑脊液显示有淋巴细胞，没有发现中性粒细胞。该患者最可能的疾病是","o":["猩红热","恙虫病","莱姆病","钩端螺旋体病","皮肤炭疽"],"a":2,"e":"最可能为莱姆病。蜱叮咬后出现逐渐扩大的环状红斑即慢性移行性红斑，继而面神经麻痹、脑膜炎和游走性关节痛；病原体为伯氏疏螺旋体，由硬蜱传播。"},{"q":"2岁患儿，因发热、呕吐、腹泻1天入院。起病6小时以来共呕吐2次，腹泻4次，为蛋花汤样水样便，无脓血，无咳嗽，无咽痛，体温38.5℃。初步判断最可能的病原体是","o":["痢疾志贺菌","肠侵袭性大肠埃希菌","轮状病毒","伤寒沙门菌","肠道腺病毒"],"a":2,"e":"最可能为轮状病毒。2岁幼儿蛋花汤样水样便、呕吐伴发热，无脓血及呼吸道症状，符合轮状病毒胃肠炎；其NSP4有肠毒素样作用，使肠液分泌增加、重吸收减少。"},{"q":"患者，女，43岁，因高热15天就诊。血常规：白细胞3、5×109/L。肝肋下触及1cm，脾肋下触及2cm。肥达反应结果为TO 1∶160，TH 1∶320，PA 1∶40，PB 1∶40。为明确诊断，应做哪项检查","o":["抗O试验","协同凝集试验","外斐反应","取血液或骨髓直接进行革兰氏染色","取粪便进行培养"],"a":4,"e":"应取粪便进行培养。肥达反应O、H效价升高提示伤寒，病程已两周，此时粪便和尿液培养阳性率较高，可分离病原菌确诊；血培养以第1周阳性率最高。"},{"q":"患者，女，20岁。旅行归来的次日出现低热，食欲缺乏，然后水样便达15次之多，无里急后重感，腹痛为轻中度，伴有恶心和乏力。有轻度脱水，体温38℃。便常规：镜下未见红、白细胞。血常规：白细胞5.6×109/L，中性粒细胞占0.8。此患者最有可能的感染是","o":["沙门菌感染","肠产毒素型大肠埃希菌","霍乱弧菌","肠出血型大肠埃希菌","志贺菌感染"],"a":1,"e":"最可能为肠产毒素型大肠埃希菌感染。旅行后低热、水样便每日十余次、无里急后重、便中无红白细胞，符合ETEC腹泻；该菌经污染食物和水传播，肠毒素使cAMP升高。"},{"q":"某幼儿园某日出现数十例集体性流感样症状患者，经胶体金法初筛A型流感阳性。如需进行流感病毒核酸分亚型检测，可采集的临床标本是","o":["鼻咽拭子","血浆标本","尿液","肛拭子","血清标本"],"a":0,"e":"应采集鼻咽拭子。流感病毒主要侵犯呼吸道上皮，核酸检测取鼻咽拭子或咽漱液阳性率最高；血浆、尿液和肛拭子病毒含量低，血清仅用于抗体检测。"},{"q":"地震时，某学生被埋在废墟下，3天3夜才被救出。左下肢开放性伤口，污染大量泥土，部分肌肉组织已出现坏死。入院后被诊断为气性坏疽。引起气性坏疽的病原菌在繁殖过程中能够","o":["合成抗生素","合成内毒素","合成维生素","合成卵磷脂酶","合成金黄色色素"],"a":3,"e":"气性坏疽由产气荚膜梭菌引起，其α毒素即卵磷脂酶，能分解细胞膜卵磷脂，造成溶血、组织坏死和血管通透性增加。该毒素在气性坏疽形成中起主要作用。"},{"q":"患者3天前开始感觉前额痛，入院当天上午高热、寒战，下午起开始出现神志不清、晕厥，随即送入医院。查体：T 41℃，BP 70/30mmHg，P 140次/min，R 24次/min，患者间断清醒，躯干有几处淤斑，鼻腔、口腔有出血，颈部柔软，无脑膜刺激征，心脏未闻及杂音，腹部除见左上四分之一象限脾切除手术瘢痕外无异常发现。胸部X光：心、肺无异常。实验室检查：血培养可见革兰染色阳性、柳叶刀状双球菌。血琼脂再次培养可见细小、半透明的、呈α-溶血环的菌落，该菌可被胆汁溶解，并可被奥普托辛（optochin）抑制。用含有抗83型肺炎链球菌的抗体的全血清做荚膜肿胀试验阳性。最有可能引起该患者败血症的病原菌是","o":["脑膜炎球菌","肺炎链球菌","流感嗜血杆菌","A群链球菌","金黄色葡萄球菌"],"a":1,"e":"最可能为肺炎链球菌。革兰阳性柳叶刀状双球菌，血平板呈α溶血，可被胆汁溶解、被奥普托辛抑制，荚膜肿胀试验阳性，均是其鉴定依据；脾切除后易发生该菌败血症。"},{"q":"患儿，女，5岁，因高热、意识模糊而入院。查体发现患儿面色苍白，昏迷，时有惊厥，两瞳孔不等大，呼吸微弱。粪检有脓细胞4个，白细胞数16×109/L，脑脊液正常。常规粪便培养发现有革兰阴性杆菌，无动力。临床诊断为中毒型痢疾。该患儿所感染病原体的主要致病物质是","o":["芽孢","鞭毛","菌毛","内毒素和外毒素","外毒素"],"a":3,"e":"主要致病物质为内毒素和外毒素。志贺菌的侵袭力使细菌侵入结肠黏膜，内毒素引起微循环障碍、DIC和脑水肿，外毒素即志贺毒素致肠黏膜损伤，故中毒型痢疾全身症状重。"},{"q":"一女性患者在无照诊所输液后不久，出现发热反应症状。导致该患者发热最有可能的成分是","o":["外毒素","肠毒素","细胞毒素","肉毒毒素","热原质"],"a":4,"e":"最可能是热原质。热原质多为革兰阴性菌细胞壁脂多糖，注入体内引起发热，耐高温，121℃高压蒸汽灭菌不被破坏，需250℃干烤才能去除，注射药品中不得含有。"},{"q":"一位在珠海拱北口岸入境的旅客出现剧烈腹痛、腹泻、呕吐等症状。经流行病学调查及患者临床症状和体征，结合实验室检测结果，确定该患者为副溶血性弧菌所致。该菌的培养特性是","o":["培养时应在培养基中加入黄绿","必须采用厌氧培养基培养","只能在巧克力色培养基上生长","培养3～4周形成肉眼可见菌落","在无盐培养基上不能生长"],"a":4,"e":"副溶血性弧菌具有嗜盐性，在含35g/L氯化钠的培养基中生长最佳，无盐培养基上不能生长，氯化钠浓度高于80g/L亦受抑制。该菌常污染海产品，引起食物中毒。"},{"q":"一位医生在给一名HBeAg阳性患者采血时，不小心刺破自己手指。下列处理最为紧要的是","o":["接种乙肝疫苗","进行酒精消毒","肌注高效价乙肝免疫球蛋白","肌注高效价乙肝表面抗原","定期复查肝功能和HBV-IgM"],"a":2,"e":"最紧要的是肌注高效价乙肝免疫球蛋白。HBeAg阳性者血液传染性强，职业暴露后应立即被动免疫以中和进入体内的病毒，同时清洗消毒伤口并接种乙肝疫苗。"},{"q":"患者，女，26岁，在剖宫产的术前例行检查中检出HIV抗体阳性。经询问，其丈夫为吸毒人员。对于该病例说法错误的是","o":["该患者的丈夫极有可能也是HIV感染者","患者的胎儿极有可能感染HIV","该患者可以正常母乳喂养婴儿","该患者的手术器械应严格的消毒灭菌","该患者的胎盘等组织块应彻底销毁"],"a":2,"e":"HIV可经胎盘、产道和乳汁传播，感染者不应母乳喂养，应人工喂养，故该说法错误。其丈夫为吸毒人员、共用注射器，感染可能性大；手术器械须严格灭菌，胎盘等组织应销毁。"},{"q":"患者，男，26岁。自诉7月在某森林探险后，突然发热，头痛、恶心、无食欲。体检发现：面神经轻瘫，表情淡漠，有脑膜刺激征。血液检测示白细胞总数升高，中性粒细胞显著增高。在下列病原微生物中，患者最有可能感染的是","o":["登革病毒","汉坦病毒","流行性感冒病毒","脊髓灰质炎病毒","森林脑炎病毒"],"a":4,"e":"最可能为森林脑炎病毒。森林探险后出现发热、头痛、脑膜刺激征及面神经轻瘫，符合蜱传脑炎；该病毒由蜱传播，蜱既是媒介又是储存宿主，病变以中枢神经系统为主。"},{"q":"患者，男，发热、休克。3日前开始头痛，入院。当日意识不清，昏迷，体温41℃，血压70/30mmHg，躯干皮肤出现红色斑点。用药后血压仍继续下降，第3天死亡。血培养发现G－茅头状双球菌生长。请问其感染的病原菌可能是","o":["溶血性链球菌","脑膜炎奈瑟菌","肠侵袭性大肠杆菌","肺炎链球菌","金黄色葡萄球菌"],"a":1,"e":"最可能为脑膜炎奈瑟菌。高热、头痛、皮肤瘀点、休克，血培养见革兰阴性矛头状双球菌，符合该菌败血症；其内毒素引起微血管栓塞与瘀斑，严重者发生DIC和休克。"},{"q":"患儿，3岁，就诊时中度发热，咳嗽、流涕、流泪、咽部充血等，以眼症状突出，包括结膜炎、眼睑水肿、眼泪增多、畏光，下眼睑边缘有一条明显充血横线（Stimson线），口腔两颊内侧黏膜查现Koplik斑。该患儿最可能的诊断是","o":["麻风","莱姆病","猩红热","副伤寒","麻疹"],"a":4,"e":"最可能为麻疹。发热、卡他症状、结膜充血畏光，颊黏膜见中心灰白、周围红色的科氏斑，是麻疹前驱期的特征性表现，也是早期诊断的重要依据。"},{"q":"部分儿童以“血便和血小板减少”入院，其中一名4岁女孩死于肾脏衰竭。流行病学调查显示所有患者都在同一家快餐店吃过牛肉汉堡。可能导致这次疾病爆发的病原体是","o":["空肠弯曲菌","非O1血清群霍乱弧菌","大肠埃希菌O157:H7","痢疾志贺菌","伤寒沙门菌"],"a":2,"e":"最可能为大肠埃希菌O157:H7。快餐店牛肉汉堡集体发病，儿童血便、血小板减少并死于肾衰竭，符合该菌引起的溶血性尿毒综合征；牛是其主要储存宿主。"},{"q":"患儿，男，12岁，昨晚在外就餐，今晨开始畏寒、发热，腹痛，腹泻伴明显里急后重；大便8次，初为稀便，继之为黏液脓血便。此病例的诊断为","o":["阿米巴痢疾","急性细菌性痢疾","急性中毒性细菌性痢疾","急性胃肠炎","慢性细菌性痢疾"],"a":1,"e":"诊断为急性细菌性痢疾。进食不洁食物后畏寒发热、腹痛、里急后重，粪便由稀便转为黏液脓血便，符合普通型急性菌痢；痢疾志贺菌侵入结肠黏膜引起炎症和溃疡。"},{"q":"患儿，女，5岁。低热，口咽部疼痛，口腔黏膜、牙龈、咽部、嘴唇以及手和脚后跟边缘呈较多水疱状病变，水疱内不含巨细胞或异常细菌。患儿最可能感染的病原体是","o":["麻疹病毒","恙虫病东方体","柯萨奇病毒","水痘-带状疱疹病毒","单纯疱疹病毒"],"a":2,"e":"最可能为柯萨奇病毒。低热伴口腔黏膜、牙龈、咽部水疱，同时手、足边缘出现水疱，符合肠道病毒所致手足口病；水疱内无巨细胞，可与巨细胞病毒感染鉴别。"},{"q":"某患者，发热头痛3天，伴恶心、呕吐和腹痛。查体：双侧肾区叩痛，低血压，右侧肘窝抽血部位可见瘀斑。尿常规示血尿、蛋白尿和白细胞尿。可考虑诊断的疾病是","o":["斑疹伤寒","猩红热","肾综合征出血热","钩体病","登革热"],"a":2,"e":"诊断为肾综合征出血热。发热头痛、肾区叩痛、低血压、抽血部位瘀斑，尿中见血尿和蛋白尿，符合汉坦病毒感染；该病毒损伤小血管内皮，引起血浆外渗、出血和肾损害。"},{"q":"患儿，8岁，半年前在脸、躯干及四肢等处出现大量皮肤小突起，不痛不痒，中心凹陷，内有干酪样塞物。涂抹多种药膏均无效。后上述突起自行消退。初步诊断该疾病是","o":["跖疣","传染性软疣","扁平疣","鲍温样丘疹","寻常疣"],"a":1,"e":"最可能为传染性软疣。儿童面部躯干出现多个中央凹陷、含干酪样物的半球形丘疹，可自行消退，由传染性软疣病毒引起；该病毒经皮肤直接接触传播，人是唯一宿主。"},{"q":"患者，男，33岁。自述每次吃饭后都出现反酸、腹胀和隐痛的现象。曾在当地的医院做过胃镜检查，诊断为胃炎。氧化酶、过氧化氢酶、脲酶分解试验均呈阳性。此患者可能感染的病原体可能为","o":["空肠弯曲菌","幽门螺杆菌","解脲脲原体","乙型肝炎病毒","金黄色葡萄球菌"],"a":1,"e":"最可能为幽门螺杆菌。该菌产生大量尿素酶，水解尿素生成氨中和胃酸，使其在胃内定植，是慢性胃炎和消化性溃疡的重要病因，尿素呼气试验据此设计。"},{"q":"患儿，男，7岁。发热伴头晕、呕吐、腹痛，嗜睡，精神差，双侧腮腺以耳垂为中心弥漫性肿大，表面皮肤正常，有触痛。双颌下腺轻度肿大，扁桃体Ⅰ度肿大，双侧睾丸肿痛、阴囊肿大。血常规白细胞轻度增高，血尿淀粉酶明显升高。头部CT右侧额叶可见局限性低密度影。该患儿最可能的疾病是","o":["流行性乙型脑炎","结核性脑膜炎","新型隐球菌脑膜炎","流行性脑膜炎","流行性腮腺炎并发脑膜炎及睾丸炎"],"a":4,"e":"最可能为流行性腮腺炎并发脑膜炎及睾丸炎。腮腺以耳垂为中心肿大伴睾丸肿痛、脑膜刺激征和血尿淀粉酶升高，符合腮腺炎病毒感染；青春期感染者易并发睾丸炎或卵巢炎。"},{"q":"5岁男孩以血便入院。经诊断为大肠埃希菌O157:H7所致，属于哪一类型的血清型","o":["EIEC","ETEC","EHEC","EPEC","EAEC"],"a":2,"e":"大肠埃希菌O157:H7属肠出血型大肠埃希菌，即EHEC，也称产志贺毒素大肠埃希菌。该型产生志贺毒素，引起血便并可并发溶血性尿毒综合征，5岁以下儿童易感。"},{"q":"患者，女，35岁。近5天出现乏力、厌油、肝大及尿色加深，诊断为“急性乙型肝炎”。该患者血液存在的物质中，具有感染性的成分是","o":["Dane颗粒","小球形颗粒","管形颗粒","HBeAg","HBV-DNA"],"a":0,"e":"具有感染性的是Dane颗粒，即大球形颗粒，直径42nm，含环状双链DNA和DNA聚合酶，是完整病毒颗粒。小球形和管形颗粒只含HBsAg，无核酸，不具感染性。"},{"q":"患者，男，27岁。发热5天，最高体温39.5℃，咳嗽，少痰，伴有头痛、肌肉酸痛和全身不适，出现呼吸困难，无胸痛。患者居住村庄近期出现大量禽类病死疫情。血常规检查显示白细胞总数减少；红细胞凝集试验阳性；胸片显示右下肺多发磨玻璃影及肺实变影像，合并少量胸腔积液。该患者最可能的诊断是","o":["肺结核","普通感冒","大叶性肺炎","人感染高致病性禽流感","严重急性呼吸综合征（SARS）"],"a":3,"e":"最可能为人感染高致病性禽流感。有禽类病死疫情接触史，发热、咳嗽、呼吸困难，白细胞减少，胸片示磨玻璃影与实变，符合甲型H5N1等禽流感病毒直接感染人。"},{"q":"患儿，男，10岁。右足底被铁锈钉刺伤10天。突然出现张嘴困难，继之出现苦笑面容，角弓反张，声响及触碰患儿可诱发上述症状。患儿神志清楚，不发热。患儿所患疾病的致病菌属于","o":["革兰染色阴性大肠杆菌","革兰染色阴性变形杆菌","革兰染色阴性厌氧拟杆菌","革兰染色阳性无芽孢厌氧菌","革兰染色阳性厌氧芽孢杆菌"],"a":4,"e":"致病菌为破伤风梭菌，属革兰染色阳性厌氧芽胞杆菌，芽胞位于顶端呈鼓槌状，专性厌氧。其痉挛毒素阻断抑制性神经递质释放，引起骨骼肌强直性痉挛。"},{"q":"某患者，肌肉酸痛，高热，剧烈头痛，入院。体格检查、外斐反应结果诊断为立克次体感染。试问预防立克次体病最重要的是","o":["注射疫苗","服用抗生素","控制和消灭传播媒介和储存宿主","灭蚊、灭蝇，防止蚊蝇叮咬","避免与病人接触"],"a":2,"e":"预防立克次体病最重要的是控制和消灭传播媒介与储存宿主。立克次体以虱、蚤、蜱、螨等节肢动物为媒介和储存宿主，灭虱灭蚤灭蜱可阻断传播；疫苗和抗生素用于个体防护。"},{"q":"患儿，男，8岁，临床隔离期间出现呼吸道卡他症状，其父母均确诊为甲型流感H7N9感染病重收治入院。其姐姐（12岁）于7天前发热、咳嗽、呼吸困难，因重症肺炎及急性呼吸窘迫综合征（ARDS）抢救无效死亡，后其咽拭子核酸检测为H5N1阳性。对于该儿童（为重症病例的高危人群），一旦出现流感样症状，应采取的措施是","o":["确诊后48小时内给奥司他韦抗病毒药","确诊后给奥司他韦抗病毒药","在72小时之内给奥司他韦抗病毒药","在48小时内给奥司他韦抗病毒药","慎重，不急于给药"],"a":3,"e":"应在48小时内尽早给奥司他韦。重症流感高危儿童一旦出现流感样症状即应开始神经氨酸酶抑制剂治疗，以抑制病毒释放、缩短病程、降低病死率，不必等待病原学确诊。"},{"q":"一新生儿患脓毒血症，脓汁标本经涂片革兰染色镜检发现葡萄球菌。经鉴定该菌属金黄色葡萄球菌。从患儿体内分离的该菌可具有的特殊结构是","o":["普通菌毛","性菌毛","芽孢","荚膜","鞭毛"],"a":3,"e":"金黄色葡萄球菌具有荚膜，是其重要的表面结构和毒力因子，可抗吞噬；该菌革兰阳性呈葡萄串状，无芽胞、无鞭毛。"},{"q":"患者一个月前感到疲劳、食欲减少、体重减轻、发热、咳嗽、痰带血丝。痰标本涂片抗酸染色可见红色分支状细菌，疑似可能为结核分枝杆菌，其具有的特殊结构是","o":["分枝菌酸","荚膜","芽孢","菌毛","鞭毛"],"a":1,"e":"结核分枝杆菌的特殊结构是荚膜，此外还具有抗酸性的细胞壁和专性需氧等特征。分枝菌酸是细胞壁中的脂质成分，不属特殊结构。"},{"q":"患者，男，20岁，咳嗽数周。1个月前开始感到疲劳，食欲减退，发热2周后咳痰中带血丝，体重减轻，体温38℃。临床怀疑患肺结核，取痰做下列处置，哪项是错误的","o":["做结核菌素试验","痰浓缩集菌涂片进行抗酸染色","PCR查结核分枝杆菌核酸","痰结核分枝杆菌培养","痰培养物接种豚鼠进行动物实验"],"a":0,"e":"做结核菌素试验是错误的。该试验反映机体是否感染过结核或接种过卡介苗，属迟发型超敏反应，不能作为现症肺结核的病原学诊断；痰抗酸染色、培养、PCR和动物试验才能检出病原体。"},{"q":"患者，男，29岁。平素体健，自诉1天前面部出现点状充血疹，不痒，畏光流泪，无诱因高热头疼。就诊时查体见耳后、面颈、躯干、四肢见颜色深浅不一的点片状皮疹，压之褪色，结膜充血，咽充血，咽后壁淋巴滤泡增生，口颊黏膜现散在细白沙粒样黏膜斑。血常规白细胞数不高，异常淋巴细胞0.03。血细菌培养（－），麻疹特异性抗体IgM（－）。该患者最可能的诊断是","o":["风疹","鹅口疮","猩红热","伤寒","麻疹"],"a":4,"e":"最可能为麻疹。畏光流泪、结膜充血、颊黏膜细白沙粒样黏膜斑伴全身皮疹，符合麻疹；麻疹特异性IgM早期可阴性，不能据此排除诊断，需结合典型临床表现判断。"},{"q":"患儿，男，10岁，发热出疹3天。红疹始于面部，后向肢体扩散。A族链球菌抗原检测阴性，诊断为传染性红斑。最可能导致该病的病原体是","o":["风疹病毒","痘病毒","人乳头瘤病毒","单纯疱疹病毒","细小DNA病毒"],"a":4,"e":"最可能为细小DNA病毒。传染性红斑由人细小病毒B19引起，表现为面颊红斑并向肢体扩散，A族链球菌抗原阴性可排除猩红热；B19为无包膜单链DNA病毒。"},{"q":"患者起病急，高热，多为弛张热，伴寒战、严重头痛及全身肌肉酸痛，经实验室检查诊断为贝纳氏柯克斯体感染。下列疾病由贝纳氏柯克斯体引起的是","o":["波浪热","出血热","猩红热","战壕热","Q热"],"a":4,"e":"由贝纳柯克斯体引起的是Q热。该菌亦称Q热柯克斯体，经呼吸道和消化道侵入，引起类似流感或非典型肺炎的发热；波浪热由布鲁菌引起，战壕热由五日热巴尔通体引起。"},{"q":"患者，女，35岁，农民，突起高热，伴头痛、肌痛、眼眶痛，胸颈部可见斑片状皮疹，初步诊断为“登革热”，该病最可能的传染源是","o":["幼猪及携带病毒的家畜家禽","患者及隐性感染者","鼠类等啮齿动物","白纹伊蚊","硬蜱"],"a":1,"e":"登革热最可能的传染源是患者及隐性感染者。登革病毒经白纹伊蚊、埃及伊蚊传播，蚊是媒介；幼猪是乙脑主要传染源，鼠类是出血热宿主，硬蜱传播森林脑炎。"},{"q":"某患者，突然出现高热，乏力，伴有腓肠肌疼痛、眼结膜出血以及淋巴结肿大。印象诊断是钩体病。该病原体的主要传染源和储存宿主是","o":["猪和犬","羊和牛","鼠和犬","牛和马","鼠和猪"],"a":4,"e":"主要传染源和储存宿主是鼠和猪。带菌动物的尿液污染水源和土壤，人接触疫水后经皮肤黏膜受染，出现发热、腓肠肌压痛、结膜充血和淋巴结肿大。"},{"q":"患儿，男，4岁。急发高热，呕吐，肌肉疼痛，继之出现急性迟缓性麻痹。查体示左上肢能轻微运动，右侧下肢不能运动，巴宾斯基征阴性，腱反射消失，肌张力下降，其他无异常。3个月后随访，右下肢近端大肌群麻痹，肌肉严重萎缩，功能受限，跛行。该患儿感染的最可能的途径是","o":["呼吸道","消化道","血液和血制品","母婴传播","恙螨叮咬"],"a":1,"e":"感染途径为消化道。该患儿为脊髓灰质炎，病毒主要经粪-口途径传播，也可经呼吸道传播；病毒在肠道增殖后经病毒血症侵犯脊髓前角运动神经元，遗留弛缓性麻痹。"},{"q":"取患者脑脊液离心沉渣做墨汁负染色镜检，发现下列哪些典型结构或形态可初步诊断为新型隐球菌性脑膜炎","o":["卵圆形菌体及厚膜孢子","厚膜孢子及芽生孢子","厚膜孢子及假菌丝","芽生孢子及宽厚荚膜","假菌丝及芽生孢子"],"a":3,"e":"见到芽生孢子及宽厚荚膜可初步诊断。脑脊液墨汁负染色下新型隐球菌呈圆形菌体，外周有一圈透明肥厚荚膜，具折光性，是该菌的特征性形态。"},{"q":"患者持续发热12天到医院就诊，精神萎靡，反应淡漠，持续高热。体温39、5℃，心率80次/min，肝肋下1.5cm，脾肋下2cm。白细胞 3.4×109/L，肥达反应结果显示O 1∶80、H 1∶160，HBsAg阴性。为确定诊断，应进行检查的项目是","o":["乙型肝炎病毒抗体","甲型肝炎病毒抗体","取外周血分离培养","丙型肝炎病毒抗体","标本取骨髓液，分离培养"],"a":4,"e":"应取骨髓液分离培养。患者发热12天处于病程第2周，骨髓中病原菌检出率高于外周血；血培养以第1周阳性率最高，粪便和尿液培养自第2周起采用。"},{"q":"某老年男性患者，肺部感染入院。常规治疗后，疗效不佳。考虑到可能出现了耐药性菌株感染。此时，做抗生素敏感试验时，应选择细菌增殖的","o":["迟缓期早期","对数生长期","稳定期后期","稳定期中期","衰亡期早期"],"a":1,"e":"应选择对数生长期细菌。此期细菌形态、染色性和生理活性典型，代谢旺盛，对外界环境因素敏感，药敏结果可靠；稳定期和衰亡期细菌性状已改变。"},{"q":"患儿，男，4岁。发热，精神差，营养良好，口腔黏膜现多个水疱状病变，双手和脚掌可见红色斑丘疹，伴口腔黏膜溃疡，呈昏睡状态，对外界刺激几乎无反应。其所在幼儿园近期有类似病例出现。该患儿最可能的诊断是","o":["手足口病","水痘","麻疹","带状疱疹","风疹"],"a":0,"e":"最可能为手足口病。发热伴口腔疱疹、手足臀部红色斑丘疹，同园有类似病例，符合肠道病毒EV-A71、CVA16等所致手足口病；6个月至3岁儿童多发，可并发脑炎。"},{"q":"患者，女，25岁。外阴红肿、瘙痒、有脓性分泌物，伴尿频、尿痛3天。采集患者分泌物，涂片镜检，中性粒细胞内外均可见G－双球菌。临床诊断为淋病。该患可能经何种途径感染","o":["粪-口途径","呼吸道","性接触","蚊虫叮咬","输血"],"a":2,"e":"经性接触感染。淋病奈瑟菌主要经性接触传播，人类是其唯一宿主，病菌侵入尿道和生殖道黏膜引起化脓性炎症；分泌物涂片见中性粒细胞内革兰阴性双球菌有诊断价值。"},{"q":"患者，男，36岁，鸟语林工作人员。突然高热达40℃，剧烈头痛，伴恶心呕吐入院。查体：咽部充血疼痛，伴咳嗽，肺部听诊有湿啰音。胸片可见支气管炎型的肺浸润灶，以下叶为多。初步诊断为间质性肺炎，最可能是","o":["肺炎支原体感染","肺炎嗜衣原体感染","沙眼衣原体血清型D-K感染","鹦鹉热嗜衣原体感染","沙眼衣原体血清型A、B、Ba、C感染"],"a":3,"e":"最可能为鹦鹉热嗜衣原体感染。鸟语林工作人员有鸟类接触史，急性高热、头痛、咳嗽及支气管炎型肺浸润，符合鹦鹉热；该菌由病鸟排泄物经呼吸道传播。"},{"q":"某患者发热3天，恶心呕吐，食欲减退。头痛四肢酸痛，腰痛。球结膜充血，尿少，尿蛋白（＋＋＋）。该病例可考虑的诊断为","o":["败血症","钩体病","肾综合征出血热","肠热症","溶血性尿毒综合征"],"a":2,"e":"诊断为肾综合征出血热。发热、头痛腰痛、恶心呕吐、球结膜充血、尿少及大量蛋白尿，符合汉坦病毒感染；该病毒损伤小血管内皮，引起血浆外渗、出血和急性肾损害。"},{"q":"患者，男，36岁。主诉尿痛、尿道流脓性分泌物2天，尿道口痛性脓肿3天。发病1周前曾有过多次非婚性接触史，2天后感尿道疼痛，尤其小便时为甚，尿道口有脓性分泌物流出。入院后，经各项检查符合淋病奈瑟菌引起的尿道炎诊断。培养淋病奈瑟菌时应注意","o":["初次分离培养时应提供5%～10%的二氧化碳气体","培养基中形成羽毛养菌落即为该菌的典型特征","应在培养基中加入蛋黄、孔雀绿等必要的成分","此菌在液体培养基中生长加入胆盐后菌体自溶","在培养基中加入适量青霉素菌体呈串珠样改变"],"a":0,"e":"初次分离培养时应提供5%～10%的二氧化碳。淋病奈瑟菌为专性需氧、营养要求高的革兰阴性双球菌，常用巧克力血琼脂平板，在5%～10%CO2环境中才能生长。"},{"q":"患者，女，30岁。因黄疸、腹胀、乏力2天入院。查体肝脏肋下两指、巩膜皮肤轻度黄染，实验室检查结果显示转氨酶明显升高，HBsAb（＋）。患者无输血史，2周前曾外出与同乡聚会吃海鲜。该患者应进一步检查的血清学指标是","o":["HBV和HCV IgM","HAV和HEV IgM","HBV和HDV IgM","HAV和HCV IgM","HDV和HEV IgM"],"a":1,"e":"应进一步查HAV和HEV IgM。患者HBsAb阳性提示对HBV已有免疫力，无输血史而近期食用海鲜，应考虑经消化道传播的甲型或戊型肝炎；抗-HAV IgM出现早，是早期诊断指标。"},{"q":"患者，男，40岁，农民。因“突起发热、头晕与头痛1周”就诊。查体：眼结膜充血、轻度黄疸、腓肠肌有明显压痛，初诊为钩体病。为协助诊断，下列检查方法，不正确的是","o":["取血标本做核酸检测","取血标本做显微镜凝集试验","取血标本接种Korthof培养基做病原培养","取血标本做快速血浆反应素试验（RPR试验）","血标本直接显微镜镜检"],"a":3,"e":"取血做快速血浆反应素试验是错误的。RPR是梅毒螺旋体的非特异性血清学试验，与钩体病无关；钩体病可取血做核酸检测、显微镜凝集试验、Korthof培养基培养或暗视野镜检。"},{"q":"患儿，女，6月龄，持续性高热，伴咳嗽、流涕，吃奶及饮水时呛咳明显，声音嘶哑，气促明显，颜面及躯干可见红色斑丘疹，四肢皮疹不明显，双眼结膜充血，眼部分泌物较多，咽部充血，双侧颊黏膜可见中心灰白周围红色特征斑，双肺呼吸音粗，可及较多中细湿啰音。否认麻疹接触史，按时按序接种疫苗。胸片示双肺纹理粗，右下肺可见斑片状渗出影。血常规示白细胞升高。该患儿最可能的诊断是","o":["风疹","副伤寒","麻疹合并支气管肺炎","猩红热","白假丝酵母菌致鹅口疮合并肺炎"],"a":2,"e":"最可能为麻疹合并支气管肺炎。6月龄婴儿持续高热、卡他症状、结膜充血、颊黏膜见特征性黏膜斑，胸片示右下肺渗出，符合麻疹并发肺炎；科氏斑是早期诊断依据。"},{"q":"患者，男，33岁，家住伦敦市郊，喜食牛排。近期出现严重进行性神经系统症状如精神异常、小脑共济失调、痴呆等，经诊断为变异型克罗伊茨费尔特-雅各布病。关于该类疾病，以下说法错误的是","o":["潜伏期长，可达10～30年","具备传染性","致病因子只存在于患者中枢神经系统中","该致病因子还可引起牛海绵状脑病","由朊粒引起"],"a":2,"e":"致病因子只存在于患者中枢神经系统中，该说法错误。朊粒病潜伏期可达数年至数十年，具传染性，致病因子除中枢神经系统外还存在于淋巴组织等部位，并可致牛海绵状脑病。"},{"q":"患儿，男，12岁。3周前，不慎被锐器扎伤右足根部，未经医生处理，自行包扎。两周后张嘴感觉下颌关节发紧，住院治疗。查体：T 38.6℃，苦笑面容，口角稍下垂，牙关紧，张口困难，颜面、口唇无发绀，脊柱和四肢无畸形，上肢活动尚可，下肢步态不稳，迈步困难，关节活动不利，右下肢肌肉间断性抽搐，足跟伤口周围红肿明显，有脓性分泌物。引起该病的病原菌生物学特点是","o":["不形成芽孢","生长最适pH为8.8～9","最适生长温度为22℃","能够进行需氧呼吸","唯一产能途径是糖酵解"],"a":4,"e":"该病为破伤风。破伤风梭菌为专性厌氧芽胞杆菌，只能经糖酵解即发酵途径获取能量，是其重要代谢特点；最适生长温度约37℃，最适pH近中性，不能进行需氧呼吸。"},{"q":"某急性肝炎患者，血清学检查显示HBsAg（＋），HBeAg（＋），抗-HBc IgM（＋）。以下对于HBeAg的叙述，错误的是","o":["血清阳性表示传染性高","存在于Dane颗粒的最外层","疾病慢性化可表现为血清持续阳性","化学成分为可溶性蛋白","其相应抗体有一定保护作用"],"a":1,"e":"存在于Dane颗粒最外层是错误的。HBeAg是可溶性蛋白，游离存在于血清中，并非病毒颗粒的表面成分，Dane颗粒最外层为HBsAg；HBeAg阳性提示病毒复制活跃、传染性强。"},{"q":"患者，男，15岁，学生。3天前突然高热达39℃，伴发冷和寒战，同时出现剧烈头痛，频繁呕吐，呈喷射性，吐出食物和胆汁，无上腹部不适，进食少，二便正常。查体可见皮肤散在少量出血点和脑膜刺激征。既往体健，无胃病和结核病史，无药物过敏史，所在学校有类似患者发生。请问可能感染的病原体是","o":["乙型脑炎病毒","脑膜炎奈瑟菌","肠侵袭性大肠杆菌","肺炎链球菌","金黄色葡萄球菌"],"a":1,"e":"最可能为脑膜炎奈瑟菌。高热、剧烈头痛、喷射性呕吐、皮肤出血点及脑膜刺激征，学校有类似病例，符合流行性脑脊髓膜炎；该菌经飞沫传播，内毒素致血管损害和瘀点。"},{"q":"患者，女，62岁，农民。右前臂结节、溃疡、淋巴结肿大2个月余，有木刺刺伤史，当地医院给予头孢他啶及局部换药治疗，症状无缓解。取皮肤组织进行真菌培养，菌落灰褐色皱膜状，显微镜下可见有隔菌丝及梨状小分生孢子，口服碘化钾治疗后症状缓解。该患者最可能感染的真菌是","o":["红色毛癣菌","白假丝酵母菌","申克孢子丝菌","新型隐球菌","烟曲霉"],"a":2,"e":"最可能为申克孢子丝菌。木刺刺伤后出现结节、溃疡及淋巴管扩散，培养见灰褐色皱膜状菌落、有隔菌丝和梨状小分生孢子，碘化钾治疗有效，均符合孢子丝菌病。"},{"q":"医院接诊一对父子，自述连续3日食用自制瓶装酸肉作为晚餐，第3日父亲开始出现恶心、呕吐、腹泻、腹痛等症状。第4日早晨儿子也开始出现上述症状，并伴有视物模糊。父子二人在当地诊所治疗后好转，但父亲从第6日开始出现吞咽困难、睁眼困难、视力模糊加重、言语不清及声音嘶哑、饮水呛咳等症状。初步诊断为肉毒梭菌感染所致，下面哪项实验可以确诊","o":["取可疑食物作为样本，进行染色镜检，发现芽孢杆菌","将患者血清与不同型别的肉毒梭菌孵育，随后与对照组分别注射小鼠。根据小鼠存活状况判断所感染菌株","取患者消化道排泄物为标本，接种于SS选择培养基中，发现无色透明菌落","患者排泄物中所含微生物为抗酸染色阳性细菌","取可疑食物进行分离培养，选取可疑菌落，接种于牛奶培养基中，出现汹涌发酵现象"],"a":1,"e":"确诊应做毒素中和试验。将患者血清与各型肉毒抗毒素孵育后接种小鼠，据小鼠存活情况判断毒素型别；染色镜检和普通培养不能确定毒素及其型别。"},{"q":"患者，女，25岁，已婚。最近发现阴道分泌物增多，呈淡黄色，污秽裤裆。白带镜检发现白细胞较多，淋球菌培养阴性。沙眼衣原体PCR检测阴性。取尿沉渣做支原体培养，生化反应显示能分解精氨酸，但不能分解尿素，在固体培养基上能长出“荷包蛋”样菌落。请问该患者最可能感染了以下哪种微生物","o":["解脲脲原体","生殖支原体","人型支原体","肺炎嗜衣原体","肺炎支原体"],"a":2,"e":"最可能为人型支原体。该菌分解精氨酸而不分解尿素，固体培养呈荷包蛋样菌落，可引起阴道分泌物增多及宫颈炎、盆腔炎；解脲脲原体分解尿素，是鉴别的关键。"},{"q":"患者，男，35岁，因腹痛、脓血便2个月入院。患者2个多月前出差回来后突然发热达38℃，无寒战，同时有腹痛、腹泻，大便每日10余次，为少量脓血便，伴里急后重；曾到附近医院，化验大便有多数白细胞，口服几次庆大霉素和黄连素好转。以后虽间断服用黄连素，但仍有黏液性便，左下腹不适，自觉日渐乏力，遂来诊。化验：大便常规为黏液脓性便，白细胞20～30个/HP，偶见成堆脓球，尿常规（－）。初步诊断：慢性菌痢。引起该病的病原菌能够合成的代谢产物是","o":["硫化氢","凝固酶","溶血素","几丁质","热原质"],"a":4,"e":"该菌能合成热原质。痢疾志贺菌为革兰阴性杆菌，其细胞壁脂多糖即内毒素，注入体内能引起发热；内毒素还引起微循环障碍和肠黏膜炎症，是菌痢全身症状的基础。"},{"q":"患者，女，55岁。乏力、食欲缺乏半个月，发热、咳嗽、痰中带血6天，以“右上肺继发性肺结核，痰结核菌涂片检查（＋）”收住院治疗。致病菌的生物学特点是","o":["专性厌氧菌","繁殖速度缓慢","革兰染色阳性","合成大量尿素酶","能够产生硫化氢"],"a":1,"e":"结核分枝杆菌繁殖速度缓慢，代时约18～24小时，培养需3～4周才见菌落。该菌为专性需氧菌，营养要求高，革兰染色不易着色，需用抗酸染色检查。"},{"q":"某大学同宿舍4名同学外出在一家路边小餐馆聚餐后，晚自习时，3名同学出现剧烈呕吐、腹泻，同时伴有中上腹部疼痛。急诊入院，初步诊断为金黄色葡萄球菌引起的“食物中毒”。此菌能够合成的代谢产物是","o":["维生素","抗生素","内毒素","外毒素","水溶性色素"],"a":3,"e":"该菌能合成外毒素。金黄色葡萄球菌食物中毒由其肠毒素引起，肠毒素属外毒素，作用于呕吐中枢，进食后1～6小时出现剧烈呕吐；该菌为革兰阳性球菌，不产生内毒素。"},{"q":"患者，男，28岁，因持续高热入院2周，诊断为急性粒细胞性白血病，化疗1周后，患者口腔黏膜上出现白色膜状物，该患者最可能感染的病原体是","o":["奋森螺旋体","白喉棒状杆菌","白假丝酵母菌","厌氧菌","变异链球菌"],"a":2,"e":"最可能为白假丝酵母菌。白血病化疗后免疫功能低下，口腔黏膜出现白色膜状物，符合鹅口疮；该菌为机会致病性真菌，在免疫缺陷者可引起黏膜及深部念珠菌病。"},{"q":"患者，女，22岁。受凉后出现寒战、发热，咳嗽，咳少许黏痰3天，自服感冒药后热退，查体：T39.5℃，急性病容，右肺呼吸音减弱，语音震颤增强，下肺大片状模糊音影。该患者抗感染治疗不宜使用的是","o":["青霉素","左氧氟沙星","阿莫西林","头孢曲松","阿米卡星"],"a":4,"e":"不宜使用阿米卡星。该患者为大叶性肺炎，病原体多为肺炎链球菌，氨基糖苷类对链球菌属天然无效；青霉素、阿莫西林、头孢曲松和左氧氟沙星均可选用。"},{"q":"患儿，女，5岁。发烧5日，咽痛，免疫接种史不详。在咽后壁、腭弓和悬雍垂等处发现灰白色膜状物，血白细胞数1.5×109/L。初步诊断最可能的病原体为","o":["细菌","病毒","真菌","支原体","衣原体"],"a":0,"e":"最可能为细菌。咽部灰白色假膜不易擦去、白细胞减少，符合白喉，病原体为白喉棒状杆菌；假膜由菌体、坏死上皮和炎性渗出物构成，外毒素吸收入血致全身中毒。"},{"q":"某急性肝炎患者，血清学检测显示HBsAg（＋），HBeAg（＋），抗-HBc（＋）。传播该病原体的途径不包括","o":["粪-口途径","分娩和哺乳","共用牙刷、剃须刀等","性接触","输血、血浆及血液制品"],"a":0,"e":"不包括粪-口途径。HBV主要经血液、血制品、性接触和母婴（分娩、哺乳）传播，共用牙刷、剃须刀可经微量血液传播；粪-口途径是甲型和戊型肝炎的传播方式。"},{"q":"患者，男，40岁，到海滨城市旅游，食用海鲜24小时后出现呕吐、腹泻、头痛，诊断为急性胃肠炎。最可能感染的病原体是","o":["星状病毒","诺如病毒","肠道病毒71型","甲型肝炎病毒","A组轮状病毒"],"a":1,"e":"最可能为诺如病毒。食用海鲜后24小时出现呕吐、腹泻和头痛，符合诺如病毒急性胃肠炎；该病毒经粪-口及污染食物、水源传播，潜伏期24～48小时，症状突然出现。"},{"q":"患儿，男，3个月。口服脊髓灰质炎减毒活疫苗11天后，开始出现发热伴轻度咳嗽，无寒战、抽搐。退热后发生下运动神经元不对称性麻痹，脑脊液示蛋白-细胞分离，肌电图示神经源性受损，脊髓、头部MRI未见异常。该患儿最可能的诊断是","o":["海绵状脑病","流行性乙型脑炎","肉毒毒素中毒","疫苗相关麻痹型脊髓灰质炎","无菌性脑膜炎"],"a":3,"e":"最可能为疫苗相关麻痹型脊髓灰质炎。口服减毒活疫苗后出现不对称弛缓性麻痹，脑脊液呈蛋白-细胞分离，符合疫苗衍生病毒侵犯脊髓前角所致的麻痹。"},{"q":"患者，女，26岁，因发热、咳嗽、眼结膜炎、米糠样皮疹在市传染病院诊断为麻疹，否认麻疹接触史，否认幼时患过麻疹。其有3月龄婴儿，平时因带娃喂奶等与婴儿密切接触。针对该婴儿可采取的预防措施是","o":["抗病毒治疗","接种减毒活疫苗","注射丙种球蛋白","接种灭活疫苗","防止硬蜱叮咬"],"a":2,"e":"应给婴儿注射丙种球蛋白。3月龄婴儿未到接种麻疹疫苗年龄，接触麻疹患者后尽早被动免疫可避免发病或减轻症状；灭活疫苗和减毒活疫苗均不用于小婴儿的紧急预防。"},{"q":"患者，女，32岁，近10天出现畏寒发热，高热持续1周。血常规：白细胞3.2×109/L。肥达反应：TO 1∶320，TH 1∶320，PA 1∶40，PB 1∶40。最可能诊断为","o":["霍乱","疟疾","钩端螺旋体病","副伤寒","伤寒"],"a":4,"e":"最可能为伤寒。持续高热、白细胞减少，肥达反应O、H效价均达1:320而副伤寒抗体阴性，符合伤寒沙门菌感染；该菌属D群，O抗原为9、12，H抗原为d。"},{"q":"某校多名学生在食堂进餐后数小时出现恶心、呕吐症状。取剩余食物作细菌培养，革兰染色并在显微镜下观察到革兰阳性的球菌，培养物可分解甘露醇，检测血浆凝固酶和耐热核酸酶试验阳性。该致病菌还有何其他特点","o":["SPA是重要的抗原和致病物质","不耐低温和干燥","属于条件致病菌","可形成双层溶血环","有鞭毛，有芽孢"],"a":0,"e":"该菌为金黄色葡萄球菌，其SPA是重要的抗原和致病物质。SPA存在于细胞壁，能与IgG的Fc段结合，具有抗吞噬作用并参与炎症损伤，是其致病与血清学鉴定的重要依据。"},{"q":"患者，男，同性恋，被确诊为HIV感染者，病后5年患者出现明显的消瘦衰竭，反复发生肺部感染，造成其免疫功能低下的机制主要是","o":["树突状细胞减少","吞噬细胞被破坏","中和抗体保护作用下降","CD4+T淋巴细胞被大量破坏","CD8+T淋巴细胞被大量破坏"],"a":3,"e":"机制是CD4+T淋巴细胞被大量破坏。HIV以CD4+T细胞为主要靶细胞，通过直接杀伤、合胞体形成、诱导凋亡及抑制生成使其数量减少和功能下降，导致细胞免疫严重缺陷。"},{"q":"患儿，女，4岁，因发烧、游走性关节炎和心肌炎而入院。其父母陈述大约两周前，该患儿出现严重的喉痛，伴发烧和胃痛，但病情几天后自然地消退。入院前两天，患儿开始出现面部、颈部和四肢奇怪的运动，这些在检查中发现是无意识、无目的、不适当的运动。实验室检查显示白细胞增多，蛋白水平升高，血沉速度升高，常规血培养结果阴性，但患儿血清中发现高滴度抗链球菌溶血素O抗体。该患儿最可能患的是","o":["急性风湿热","链球菌性的心内膜炎","破伤风","白喉","小儿麻痹症"],"a":0,"e":"最可能为急性风湿热。咽峡炎后2～4周出现游走性关节炎、心肌炎及舞蹈样不自主动作，抗链球菌溶血素O升高，符合A群链球菌感染后的Ⅱ、Ⅲ型超敏反应。"}];
